-- pokemon_db 데이터베이스 구조 내보내기
CREATE DATABASE IF NOT EXISTS `pokemon_db` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci */;
USE `pokemon_db`;

-- 테이블 pokemon_db.abilities 구조 내보내기
CREATE TABLE IF NOT EXISTS `abilities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name_en` varchar(1000) DEFAULT NULL,
  `name_ko` varchar(1000) DEFAULT NULL,
  `desc_ko` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.abilities:~80 rows (대략적) 내보내기

-- 테이블 pokemon_db.backgrounds 구조 내보내기
CREATE TABLE IF NOT EXISTS `backgrounds` (
  `location_id` int(11) NOT NULL,
  `background_url` varchar(500) DEFAULT '/static/images/bg_road.png',
  PRIMARY KEY (`location_id`),
  CONSTRAINT `fk_background_location` FOREIGN KEY (`location_id`) REFERENCES `locations` (`location_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.backgrounds:~1,070 rows (대략적) 내보내기

-- 테이블 pokemon_db.encounters 구조 내보내기
CREATE TABLE IF NOT EXISTS `encounters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `location_id` int(11) DEFAULT NULL,
  `pokemon_id` int(11) DEFAULT NULL,
  `encounter_rate` int(11) DEFAULT NULL,
  `min_level` int(11) DEFAULT NULL,
  `max_level` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9240 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.encounters:~9,186 rows (대략적) 내보내기

-- 테이블 pokemon_db.inventory 구조 내보내기
CREATE TABLE IF NOT EXISTS `inventory` (
  `user_id` int(11) DEFAULT NULL,
  `item_id` int(11) DEFAULT NULL,
  `count` int(11) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.inventory:~29 rows (대략적) 내보내기

-- 테이블 pokemon_db.items 구조 내보내기
CREATE TABLE IF NOT EXISTS `items` (
  `item_id` int(11) NOT NULL AUTO_INCREMENT,
  `name_en` varchar(1000) DEFAULT NULL,
  `name_ko` varchar(1000) DEFAULT NULL,
  `price` int(11) DEFAULT NULL,
  `effect_ko` varchar(1000) DEFAULT NULL,
  `category` varchar(1000) DEFAULT NULL,
  `img_url` varchar(1000) DEFAULT NULL,
  `function_type` varchar(1000) DEFAULT NULL,
  `value` varchar(1000) DEFAULT NULL,
  `heal_amount` int(11) DEFAULT 0,
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10003 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.items:~2,168 rows (대략적) 내보내기

-- 테이블 pokemon_db.locations 구조 내보내기
CREATE TABLE IF NOT EXISTS `locations` (
  `location_id` int(11) NOT NULL AUTO_INCREMENT,
  `region` varchar(1000) DEFAULT NULL,
  `name_en` varchar(1000) DEFAULT NULL,
  `name_ko` varchar(1000) DEFAULT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `floor_range_start` int(11) DEFAULT 1,
  `floor_range_end` int(11) DEFAULT 10,
  PRIMARY KEY (`location_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1088 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.locations:~1,070 rows (대략적) 내보내기

-- 테이블 pokemon_db.moves 구조 내보내기
CREATE TABLE IF NOT EXISTS `moves` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(1000) DEFAULT NULL,
  `type` varchar(1000) DEFAULT NULL,
  `category` varchar(1000) DEFAULT NULL,
  `power` int(11) DEFAULT NULL,
  `accuracy` int(11) DEFAULT NULL,
  `pp` int(11) DEFAULT NULL,
  `effect` varchar(1000) DEFAULT NULL,
  `prob` int(11) DEFAULT NULL,
  `name_ko` varchar(1000) DEFAULT NULL,
  `effect_ko` varchar(1000) DEFAULT NULL,
  `priority` varchar(1000) DEFAULT NULL,
  `target` varchar(1000) DEFAULT NULL,
  `stat_change` varchar(1000) DEFAULT NULL,
  `status_effect` varchar(1000) DEFAULT NULL,
  `damage_class` varchar(1000) DEFAULT NULL,
  `flavor_text_ko` varchar(1000) DEFAULT NULL,
  `type_ko` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1924 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.moves:~1,925 rows (대략적) 내보내기

-- 테이블 pokemon_db.my_pokemon 구조 내보내기
CREATE TABLE IF NOT EXISTS `my_pokemon` (
  `slot_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `pokemon_dex_id` int(11) NOT NULL COMMENT 'pokemon_full_info의 id 참조',
  `nickname` varchar(100) DEFAULT NULL,
  `level` int(11) DEFAULT 5,
  `current_hp` int(11) DEFAULT 0,
  `max_hp` int(11) DEFAULT NULL,
  `attack` int(11) DEFAULT NULL,
  `defense` int(11) DEFAULT NULL,
  `sp_attack` int(11) DEFAULT NULL,
  `sp_defense` int(11) DEFAULT NULL,
  `speed` int(11) DEFAULT NULL,
  `is_in_party` tinyint(1) DEFAULT 0 COMMENT '1이면 파티, 0이면 PC',
  `slot_position` int(11) DEFAULT NULL COMMENT '파티 내 순서 1~6',
  `move1_id` int(11) DEFAULT NULL COMMENT 'pokemon_moves 참조',
  `move2_id` int(11) DEFAULT NULL,
  `move3_id` int(11) DEFAULT NULL,
  `move4_id` int(11) DEFAULT NULL,
  `my_slot_id` int(11) DEFAULT 0,
  `max_hp_iv` int(11) DEFAULT 0 COMMENT '개체값 0~31',
  `attack_iv` int(11) DEFAULT 0,
  `defense_iv` int(11) DEFAULT 0,
  `speed_iv` int(11) DEFAULT 0,
  `sp_atk_iv` int(11) DEFAULT 0,
  `sp_def_iv` int(11) DEFAULT 0,
  `name_en` varchar(255) DEFAULT NULL,
  `exp` int(11) DEFAULT 0 COMMENT '현재 경험치',
  `friendship` int(11) DEFAULT 0 COMMENT '친밀도',
  PRIMARY KEY (`slot_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.my_pokemon:~17 rows (대략적) 내보내기

-- 테이블 pokemon_db.pokedex_progress 구조 내보내기
CREATE TABLE IF NOT EXISTS `pokedex_progress` (
  `user_id` int(11) DEFAULT NULL,
  `pokemon_id` int(11) DEFAULT NULL,
  `status` varchar(1000) DEFAULT NULL,
  `first_seen_at` varchar(1000) DEFAULT NULL,
  `is_caught` tinyint(1) DEFAULT 0,
  `is_seen` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.pokedex_progress:~68 rows (대략적) 내보내기

-- 테이블 pokemon_db.pokemon_abilities 구조 내보내기
CREATE TABLE IF NOT EXISTS `pokemon_abilities` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pokemon_id` int(11) DEFAULT NULL,
  `ability_id` int(11) DEFAULT NULL,
  `ability_name` varchar(1000) DEFAULT NULL,
  `is_hidden` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_pa_pokemon` (`pokemon_id`),
  KEY `fk_pa_ability` (`ability_id`),
  CONSTRAINT `fk_pa_ability` FOREIGN KEY (`ability_id`) REFERENCES `abilities` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pa_pokemon` FOREIGN KEY (`pokemon_id`) REFERENCES `pokemon_full_info` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3066 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- 테이블 데이터 pokemon_db.pokemon_abilities:~211 rows (대략적) 내보내기

-- 테이블 pokemon_db.pokemon_evolution 구조 내보내기
CREATE TABLE IF NOT EXISTS `pokemon_evolution` (
