INSERT IGNORE INTO `items` (`item_id`, `name_en`, `name_ko`, `price`, `effect_ko`, `category`, `img_url`, `function_type`, `value`, `heal_amount`) VALUES
	(1, 'Master Ball', '마스터볼', 0, '야생 포켓몬을 반드시 잡을 수 있는 최고 성능의 볼.', 'standard-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/master-ball.png', 'catch', '255', 0),
	(2, 'Ultra Ball', '하이퍼볼', 800, '수퍼볼보다도 더욱 포켓몬을 잡기 쉬워진 매우 성능이 좋은 볼.', 'standard-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ultra-ball.png', 'catch', '20', 0),
	(3, 'Great Ball', '수퍼볼', 600, '몬스터볼보다도 더욱 포켓몬을 잡기 쉬워진 약간 성능이 좋은 볼.', 'standard-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/great-ball.png', 'catch', '15', 0),
	(4, 'Poké Ball', '몬스터볼', 200, '야생 포켓몬에게 던져서 잡기 위한 볼. 캡슐식으로 되어 있다.', 'standard-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/poke-ball.png', 'catch', '10', 0),
	(5, 'Safari Ball', '사파리볼', 0, '대습초원 안에서만 쓰는 특별한 볼. 얼룩무늬로 되어 있다.', 'standard-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/safari-ball.png', 'catch', '10', 0),
	(6, 'Net Ball', '넷트볼', 1000, '물타입과 벌레타입의 포켓몬을 잡기 쉬운 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/net-ball.png', 'catch', '10', 0),
	(7, 'Dive Ball', '다이브볼', 1000, '물의 세계에서 사는 포켓몬을 잡기 쉬운 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/dive-ball.png', 'catch', '10', 0),
	(8, 'Nest Ball', '네스트볼', 1000, '잡으려는 야생 포켓몬이 약할수록 잡기 쉬운 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/nest-ball.png', 'catch', '10', 0),
	(9, 'Repeat Ball', '리피드볼', 1000, '잡은 적이 있는 포켓몬을 잡기 쉬운 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/repeat-ball.png', 'catch', '10', 0),
	(10, 'Timer Ball', '타이마볼', 1000, '턴 수가 길어지면 길어질수록 포켓몬을 잡기 쉬운 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/timer-ball.png', 'catch', '10', 0),
	(11, 'Luxury Ball', '럭셔리볼', 3000, '잡은 야생 포켓몬이 매우 친밀해지기 쉬운 편안한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/luxury-ball.png', 'catch', '10', 0),
	(12, 'Premier Ball', '프레미어볼', 20, '무언가의 기념품으로 특별히 만들어진 조금 희귀한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/premier-ball.png', 'catch', '10', 0),
	(13, 'Dusk Ball', '다크볼', 1000, '밤이나 동굴 등 어두운 곳에서 포켓몬을 잡기 쉬운 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/dusk-ball.png', 'catch', '10', 0),
	(14, 'Heal Ball', '힐볼', 300, '잡은 포켓몬의 HP와 상태 이상을 회복시키는 조금 다정한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/heal-ball.png', 'catch', '10', 0),
	(15, 'Quick Ball', '퀵볼', 1000, '배틀이 시작되자마자 사용하면 잡기 쉬워지는 조금 특이한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/quick-ball.png', 'catch', '10', 0),
	(16, 'Cherish Ball', '프레셔스볼', 0, '무언가의 기념품으로 특별히 만들어진 상당히 진귀한 볼.', 'special-balls', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/cherish-ball.png', 'catch', '10', 0),
	(17, 'Potion', '상처약', 200, '스프레이식의 상처약. 포켓몬 1마리의 HP를 20만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/potion.png', 'heal', '20', 20),
	(18, 'Antidote', '해독제', 200, '스프레이식의 약. 포켓몬 1마리의 독 상태를 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/antidote.png', NULL, NULL, 0),
	(19, 'Burn Heal', '화상치료제', 200, '스프레이식의 약. 포켓몬 1마리의 화상 상태를 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/burn-heal.png', NULL, NULL, 0),
	(20, 'Ice Heal', '얼음상태치료제', 200, '스프레이식의 약. 포켓몬 1마리의 얼음 상태를 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ice-heal.png', NULL, NULL, 0),
	(21, 'Awakening', '잠깨는약', 200, '스프레이식의 약. 포켓몬 1마리의 잠듦 상태를 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/awakening.png', NULL, NULL, 0),
	(22, 'Paralyze Heal', '마비치료제', 200, '스프레이식의 약. 포켓몬 1마리의 마비 상태를 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/paralyze-heal.png', NULL, NULL, 0),
	(23, 'Full Restore', '회복약', 3000, '포켓몬 1마리의 HP와 상태 이상을 모두 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/full-restore.png', NULL, NULL, 0),
	(24, 'Max Potion', '풀회복약', 2500, '스프레이식의 상처약. 포켓몬 1마리의 HP를 모두 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/max-potion.png', 'heal', '999', 999),
	(25, 'Hyper Potion', '고급상처약', 1500, '스프레이식의 상처약. 포켓몬 1마리의 HP를 200만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/hyper-potion.png', 'heal', '200', 200),
	(26, 'Super Potion', '좋은상처약', 700, '스프레이식의 상처약. 포켓몬 1마리의 HP를 50만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/super-potion.png', 'heal', '50', 50),
	(27, 'Full Heal', '만병통치제', 400, '스프레이식의 약. 포켓몬 1마리의 상태 이상을 모두 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/full-heal.png', NULL, NULL, 0),
	(28, 'Revive', '기력의조각', 2000, '기절해 버린 포켓몬 1마리를 건강하게 하고 HP를 절반까지 회복한다.', 'revival', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/revive.png', NULL, NULL, 0),
	(29, 'Max Revive', '기력의덩어리', 4000, '기절해 버린 포켓몬 1마리를 건강하게 하고 HP를 모두 회복한다.', 'revival', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/max-revive.png', NULL, NULL, 0),
	(30, 'Fresh Water', '맛있는물', 200, '미네랄이 가득한 물. 포켓몬 1마리의 HP를 50만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/fresh-water.png', 'heal', '50', 50),
	(31, 'Soda Pop', '미네랄사이다', 300, '싸하고 톡 쏘는 사이다. 포켓몬 1마리의 HP를 60만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/soda-pop.png', 'heal', '60', 60),
	(32, 'Lemonade', '후르츠밀크', 400, '매우 달콤한 쥬스. 포켓몬 1마리의 HP를 80만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/lemonade.png', NULL, NULL, 0),
	(33, 'Moomoo Milk', '튼튼밀크', 600, '영양 만점의 우유. 포켓몬 1마리의 HP를 100만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/moomoo-milk.png', NULL, NULL, 0),
	(34, 'Energy Powder', '힘의가루', 500, '매우 쓴 가루약. 포켓몬 1마리의 HP를 50만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/energy-powder.png', NULL, NULL, 0),
	(35, 'Energy Root', '힘의뿌리', 1200, '매우 쓴 뿌리. 포켓몬 1마리의 HP를 200만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/energy-root.png', NULL, NULL, 0),
	(36, 'Heal Powder', '만능가루', 300, '매우 쓴 가루약. 포켓몬 1마리의 상태 이상을 모두 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/heal-powder.png', NULL, NULL, 0),
	(37, 'Revival Herb', '부활초', 2800, '매우 쓴 약초. 기절한 포켓몬 1마리의 HP를 모두 회복한다.', 'revival', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/revival-herb.png', NULL, NULL, 0),
	(38, 'Ether', 'PP에이드', 1200, '포켓몬이 기억하고 있는 기술 중 1개의 PP를 10만큼 회복한다.', 'pp-recovery', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/ether.png', NULL, NULL, 0),
	(39, 'Max Ether', 'PP회복', 2000, '포켓몬이 기억하고 있는 기술 중 1개의 PP를 모두 회복한다.', 'pp-recovery', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/max-ether.png', NULL, NULL, 0),
	(40, 'Elixir', 'PP에이더', 3000, '포켓몬이 기억하고 있는 4개 기술의 PP를 10씩 회복한다.', 'pp-recovery', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/elixir.png', NULL, NULL, 0),
	(41, 'Max Elixir', 'PP맥스', 4500, '포켓몬이 기억하고 있는 4개 기술의 PP를 모두 회복한다.', 'pp-recovery', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/max-elixir.png', NULL, NULL, 0),
	(42, 'Lava Cookie', '용암전병', 350, '용암마을의 명물인 전병. 포켓몬 1마리의 상태 이상을 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/lava-cookie.png', NULL, NULL, 0),
	(43, 'Berry Juice', '나무열매쥬스', 200, '나무열매 100% 쥬스. 포켓몬 1마리의 HP를 20만큼 회복한다.', 'healing', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/berry-juice.png', NULL, NULL, 0),
	(44, 'Sacred Ash', '성스러운분말', 50000, '기절해 버린 포켓몬 전원의 HP를 모두 회복한다.', 'revival', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/sacred-ash.png', NULL, NULL, 0),
	(45, 'HP Up', '맥스업', 10000, '포켓몬의 영양 드링크. 포켓몬 1마리의 HP 기초 포인트를 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/hp-up.png', NULL, NULL, 0),
	(46, 'Protein', '타우린', 10000, '포켓몬의 영양 드링크. 포켓몬 1마리의 공격 기초 포인트를 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/protein.png', NULL, NULL, 0),
	(47, 'Iron', '사포닌', 10000, '포켓몬의 영양 드링크. 포켓몬 1마리의 방어 기초 포인트를 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/iron.png', NULL, NULL, 0),
	(48, 'Carbos', '알칼로이드', 10000, '포켓몬의 영양 드링크. 포켓몬 1마리의 스피드 기초 포인트를 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/carbos.png', NULL, NULL, 0),
	(49, 'Calcium', '리보플라빈', 10000, '포켓몬의 영양 드링크. 포켓몬 1마리의 특수공격 기초 포인트를 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/calcium.png', NULL, NULL, 0),
	(50, 'Rare Candy', '이상한사탕', 10000, '에너지가 가득한 사탕. 먹이면 포켓몬 1마리의 레벨이 1만큼 올라간다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/rare-candy.png', NULL, NULL, 0),
	(51, 'PP Up', '포인트업', 10000, '포켓몬이 기억하고 있는 기술 중 1개의 PP 최대치를 조금 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/pp-up.png', NULL, NULL, 0),
	(52, 'Zinc', '키토산', 10000, '포켓몬의 영양 드링크. 포켓몬 1마리의 특수방어 기초 포인트를 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/zinc.png', NULL, NULL, 0),
	(53, 'PP Max', '포인트맥스', 10000, '기억하고 있는 기술 중 1개의 PP 최대치를 최고까지 올린다.', 'vitamins', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/pp-max.png', NULL, NULL, 0),
	(54, 'Old Gateau', '숲의양갱', 350, '영원시티의 숨은 명물. 포켓몬 1마리의 상태 이상을 모두 회복한다.', 'status-cures', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/old-gateau.png', NULL, NULL, 0),
	(55, 'Guard Spec.', '이펙트가드', 1500, '배틀 중 5턴 동안 같은 편의 능력을 떨어뜨리지 않게 하는 도구.', 'stat-boosts', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/guard-spec.png', NULL, NULL, 0),
	(56, 'Dire Hit', '크리티컬커터', 1000, '급소 명중률이 크게 올라간다. 한 번밖에 쓸 수 없다. 포켓몬을 볼에 넣어버리면 원래대로 되돌아간다.', 'stat-boosts', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/dire-hit.png', NULL, NULL, 0),
