	(1301, 'Calm Mint', '차분민트', 20, '포켓몬에게 향기를 맡게 하면 특수방어가 오르기 쉬워지지만 공격이 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1302, 'Gentle Mint', '얌전민트', 20, '포켓몬에게 향기를 맡게 하면 특수방어가 오르기 쉬워지지만 방어가 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1303, 'Careful Mint', '신중민트', 20, '포켓몬에게 향기를 맡게 하면 특수방어가 오르기 쉬워지지만 특수공격이 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1304, 'Sassy Mint', '건방민트', 20, '포켓몬에게 향기를 맡게 하면 특수방어가 오르기 쉬워지지만 스피드가 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1305, 'Timid Mint', '겁쟁이민트', 20, '포켓몬에게 향기를 맡게 하면 스피드가 오르기 쉬워지지만 공격이 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1306, 'Hasty Mint', '성급민트', 20, '포켓몬에게 향기를 맡게 하면 스피드가 오르기 쉬워지지만 방어가 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1307, 'Jolly Mint', '명랑민트', 20, '포켓몬에게 향기를 맡게 하면 스피드가 오르기 쉬워지지만 특수공격이 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1308, 'Naive Mint', '천진난만민트', 20, '포켓몬에게 향기를 맡게 하면 스피드가 오르기 쉬워지지만 특수방어가 오르기 어려워지는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1309, 'Serious Mint', '성실민트', 20, '포켓몬에게 향기를 맡게 하면 공격, 방어, 스피드, 특수방어 특수공격이 골고루 오르게 되는 민트.', 'nature-mints', NULL, NULL, NULL, 0),
	(1310, 'Wishing Piece', '소원의덩어리', 20, '포켓몬굴에 던져넣으면 다이맥스 포켓몬이 나타난다.', 'collectibles', NULL, NULL, NULL, 0),
	(1311, 'Cracked Pot', '깨진포트', 1600, '어느 특정 포켓몬을 진화시키는 이상한 포트. 깨졌지만 차는 맛있어진다.', 'evolution', NULL, NULL, NULL, 0),
	(1312, 'Chipped Pot', '이빠진포트', 38000, '어느 특정 포켓몬을 진화시키는 이상한 포트. 이가 빠졌지만 차는 맛있어진다.', 'evolution', NULL, NULL, NULL, 0),
	(1313, 'Hi-tech Earbuds', '대단한귀마개', 0, '다양한 소리의 볼륨을 자유자재로 조절할 수 있는 신기하고 대단한 귀마개.', 'gameplay', NULL, NULL, NULL, 0),
	(1314, 'Fruit Bunch', '송이팩', 2200, '캠프 요리에 사용되는 식재료 중 하나. 걸쭉해진 송이가 열대지방의 기분을 느끼게 해준다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1315, 'Moomoo Cheese', '튼튼치즈', 2200, '캠프 요리에 사용되는 식재료 중 하나. 녹아내린 치즈가 카레의 감칠맛을 더해준다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1316, 'Spice Mix', '스파이스세트', 400, '캠프 요리에 사용되는 식재료 중 하나. 50가지가 넘는 향신료가 들어 있어 맵다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1317, 'Fresh Cream', '신선한크림', 950, '캠프 요리에 사용되는 식재료 중 하나. 매운 카레에 휘핑크림을 넣으면 달콤해진다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1318, 'Packaged Curry', '레토르트카레', 950, '캠프 요리에 사용되는 식재료 중 하나. 완성된 레토르트카레를 사용해서 실패를 막는다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1319, 'Coconut Milk', '야자밀크', 950, '캠프 요리에 사용되는 식재료 중 하나. 고급스러운 단맛이 나는 코코넛 밀크가 인기다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1320, 'Instant Noodles', '레토르트면', 150, '캠프 요리에 사용되는 식재료 중 하나. 인스턴트 음식의 맛이 의외로 잘 어울린다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1321, 'Precooked Burger', '레토르트햄버그', 150, '캠프 요리에 사용되는 식재료 중 하나. 고민될 때 햄버그를 넣으면 실패할 일은 없다.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1322, 'Gigantamix', '거대파우더', 15000, '캠프 요리의 식재료. 조금만 넣어도 카레를 거대하게 만드는 신기한 향신료.', 'curry-ingredients', NULL, NULL, NULL, 0),
	(1323, 'Wishing Chip', '소원의조각', 0, '포켓몬굴에 몇 개 던져넣으면 다이맥스 포켓몬이 나타날 때가 있다.', 'unused', NULL, NULL, NULL, 0),
	(1324, 'Rotom Bike', '로토무자전거', 0, '포켓몬 로토무가 모터에 들어가서 터보를 사용할 수 있게 된 자전거.', 'unused', NULL, NULL, NULL, 0),
	(1325, 'Catching Charm', '흔들림없는부적', 0, '지니고 있으면 포획 크리티컬이 나오기 쉬워지는 이상하고 잘 흔들리지 않는 부적.', 'gameplay', NULL, NULL, NULL, 0),
	(1326, 'Old Letter', '낡은편지', 0, '여자아이가 맡긴 편지. 받는 이는 남자아이로 되어 있다. 어째선지 낡아 보인다.', 'plot-advancement', NULL, NULL, NULL, 0),
	(1327, 'Band Autograph', '밴드의사인', 0, '가라르지방의 카리스마 넘치는 밴드 “맥시마이저즈” 멤버 전원의 사인.', 'unused', NULL, NULL, NULL, 0),
	(1328, 'Sonia’s Book', '소니아의책', 0, '소니아박사가 출판했다. 가라르지방의 전설에 대한 새로운 발견이 흥미롭게 쓰여 있다.', 'plot-advancement', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/sonias-book.png', NULL, NULL, 0),
	(1329, 'Rotom Catalog', '로토무카탈로그', 0, '로토무가 좋아하는 가전제품이 실려 있다. 카탈로그를 사용하면 로토무를 가전제품에 넣거나 꺼낼 수 있다.', 'gameplay', NULL, NULL, NULL, 0),
	(1330, '★And458', '★And458', 20, '사용한 당일에만 와일드에리어에 있는 감시탑의 다이맥스굴에서 [VAR (0000)][VAR (0003)] 나타난다.', 'dynamax-crystals', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/dynamax-crystal-and458.png', NULL, NULL, 0),
