INSERT IGNORE INTO `moves` (`id`, `name`, `type`, `category`, `power`, `accuracy`, `pp`, `effect`, `prob`, `name_ko`, `effect_ko`, `priority`, `target`, `stat_change`, `status_effect`, `damage_class`, `flavor_text_ko`, `type_ko`) VALUES
	(1, 'Growl', 'Normal', 'Status', 0, 100, 40, NULL, NULL, '울음소리', '귀여운 울음소리를 들려주고 관심을 끌어 방심한 사이에 상대의 공격을 떨어뜨린다.', '0', 'all-opponents', '{"attack": -1}', NULL, 'status', NULL, '노말'),
	(2, 'Tackle', 'Normal', 'Physical', 40, 100, 35, '35', 0, '몸통박치기', '상대를 향해서 몸 전체를 부딪쳐가며 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(3, 'Vine Whip', 'Grass', 'Physical', 45, 100, 25, '25', 0, '덩굴채찍', '채찍처럼 휘어지는 가늘고 긴 덩굴로 상대를 힘껏 쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(4, 'Growth', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '성장', '몸을 일시에 크게 성장시켜 공격과 특수공격을 올린다.', '0', 'user', '{"attack": 1, "special-attack": 1}', NULL, 'status', NULL, '노말'),
	(5, 'Leech Seed', 'Grass', 'Status', 0, 90, 10, NULL, NULL, '씨뿌리기', '씨가 뿌려진 상대의 HP를 매 턴 조금씩 흡수하여 자신의 HP를 회복한다.', '0', 'selected-pokemon', NULL, 'leech-seed', 'status', NULL, '풀'),
	(6, 'Razor Leaf', 'Grass', 'Physical', 55, 95, 25, NULL, NULL, '잎날가르기', '잎사귀를 날려 상대를 베어 공격한다. 급소에 맞기 쉽다.', '0', 'all-opponents', NULL, NULL, 'physical', NULL, '풀'),
	(7, 'Poison Powder', 'Poison', 'Status', 0, 75, 35, NULL, NULL, '독가루', '독이 있는 가루를 많이 흩뿌려서 상대를 독 상태로 만든다.', '0', 'selected-pokemon', NULL, 'poison', 'status', NULL, '독'),
	(8, 'Sleep Powder', 'Grass', 'Status', 0, 75, 15, NULL, NULL, '수면가루', '잠이 오는 가루를 많이 흩뿌려서 상대를 잠듦 상태로 만든다.', '0', 'selected-pokemon', NULL, 'sleep', 'status', NULL, '풀'),
	(9, 'Take Down', 'Normal', 'Physical', 90, 85, 20, NULL, NULL, '돌진', '굉장한 기세로 상대에게 부딪쳐 공격한다. 자신도 조금 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(10, 'Magical Leaf', 'Grass', 'Special', 60, 0, 20, NULL, NULL, '메지컬리프', '상대를 추적하는 이상한 잎사귀를 흩뿌린다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '풀'),
	(11, 'Synthesis', 'Grass', 'Status', 0, 0, 5, NULL, NULL, '광합성', '자신의 HP를 회복한다. 날씨에 따라 회복량이 변한다.', '0', 'user', NULL, NULL, 'status', NULL, '풀'),
	(12, 'Amnesia', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '망각술', '머리를 비워서 순간적으로 무언가를 잊어버림으로써 자신의 특수방어를 크게 올린다.', '0', 'user', '{"special-defense": 2}', NULL, 'status', NULL, '에스퍼'),
	(13, 'Sludge Wave', 'Poison', 'Special', 95, 100, 10, NULL, NULL, '오물웨이브', '오물 파도로 자신의 주위에 있는 포켓몬을 공격한다. 독 상태로 만들 때가 있다.', '0', 'all-other-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(14, 'Double-Edge', 'Normal', 'Physical', 120, 100, 15, NULL, NULL, '이판사판태클', '목숨을 걸고 상대에게 돌진하여 공격을 한다. 자신도 상당한 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(15, 'Solar Beam', 'Grass', 'Special', 120, 100, 10, NULL, NULL, '솔라빔', '1턴째에 빛을 가득 모아 2턴째에 빛의 다발을 발사하여 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '풀'),
	(16, 'Ember', 'Fire', 'Special', 40, 100, 25, NULL, NULL, '불꽃세례', '작은 불꽃을 상대에게 발사하여 공격한다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(17, 'Smokescreen', 'Normal', 'Status', 0, 100, 20, NULL, NULL, '연막', '연기나 먹물을 내뿜어 상대의 명중률을 떨어뜨린다.', '0', 'selected-pokemon', '{"accuracy": -1}', NULL, 'status', NULL, '노말'),
	(18, 'Dragon Breath', 'Dragon', 'Special', 60, 100, 20, NULL, NULL, '용의숨결', '굉장한 숨결을 상대에게 내뿜어 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'special', NULL, '드래곤'),
	(19, 'Fire Fang', 'Fire', 'Physical', 65, 95, 15, NULL, NULL, '불꽃엄니', '불꽃을 두른 이빨로 문다. 상대를 풀죽게 하거나 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'physical', NULL, '불꽃'),
	(20, 'Fire Spin', 'Fire', 'Special', 35, 85, 15, NULL, NULL, '회오리불꽃', '세차게 소용돌이치는 불꽃 속에 4-5턴 동안 상대를 가두어 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'special', NULL, '불꽃'),
	(21, 'Slash', 'Normal', 'Physical', 70, 100, 20, NULL, NULL, '베어가르기', '발톱이나 낫 등으로 상대를 베어 갈라서 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(22, 'Flamethrower', 'Fire', 'Special', 90, 100, 15, NULL, NULL, '화염방사', '세찬 불꽃을 상대에게 발사하여 공격한다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(23, 'Dragon Rush', 'Dragon', 'Physical', 100, 75, 10, NULL, NULL, '드래곤다이브', '굉장한 살기로 위압하면서 몸통박치기한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '드래곤'),
	(24, 'Flare Blitz', 'Fire', 'Physical', 120, 100, 15, NULL, NULL, '플레어드라이브', '불꽃을 두르고 돌진한다. 자신도 상당한 데미지를 입는다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'physical', NULL, '불꽃'),
	(25, 'Dragon Claw', 'Dragon', 'Physical', 80, 100, 15, '15', 0, '드래곤크루', '날카롭고 뾰족한 거대한 발톱으로 상대를 베어 갈라서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '드래곤'),
	(26, 'Tail Whip', 'Normal', 'Status', 0, 100, 30, NULL, NULL, '꼬리흔들기', '꼬리를 좌우로 귀엽게 흔들어 방심을 유도한다. 상대의 방어를 떨어뜨린다.', '0', 'all-opponents', '{"defense": -1}', NULL, 'status', NULL, '노말'),
	(27, 'Water Gun', 'Water', 'Special', 40, 100, 25, '25', 0, '물대포', '물을 기세 좋게 상대에게 발사하여 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '물'),
	(28, 'Bite', 'Dark', 'Physical', 60, 100, 25, NULL, NULL, '물기', '날카롭고 뾰족한 이빨로 물어서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(29, 'Bubble Beam', 'Water', 'Special', 65, 100, 20, NULL, NULL, '거품광선', '거품을 기세 좋게 상대에게 발사하여 공격한다. 스피드를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"speed": -1}', NULL, 'special', NULL, '물'),
	(30, 'Icy Wind', 'Ice', 'Special', 55, 95, 15, NULL, NULL, '얼다바람', '차가운 냉기를 상대에게 내뿜어 공격한다. 상대의 스피드를 떨어뜨린다.', '0', 'all-opponents', '{"speed": -1}', NULL, 'special', NULL, '얼음'),
	(31, 'Aqua Ring', 'Water', 'Status', 0, 0, 20, NULL, NULL, '아쿠아링', '자신의 몸 주변을 물로 만든 베일로 덮는다. 매 턴 HP를 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '물'),
	(32, 'Aqua Jet', 'Water', 'Physical', 40, 100, 20, NULL, NULL, '아쿠아제트', '눈에 보이지 않는 굉장한 속도로 상대에게 돌진한다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(33, 'Iron Defense', 'Steel', 'Status', 0, 0, 15, NULL, NULL, '철벽', '피부를 쇠처럼 단단하게 함으로써 자신의 방어를 크게 올린다.', '0', 'user', '{"defense": 2}', NULL, 'status', NULL, '강철'),
	(34, 'Liquidation', 'Water', 'Physical', 85, 100, 10, NULL, NULL, '아쿠아브레이크', '물의 힘으로 상대에게 부딪쳐서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '물'),
	(35, 'String Shot', 'Bug', 'Status', 0, 95, 40, NULL, NULL, '실뿜기', '입에서 뿜어낸 실을 휘감아서 상대의 스피드를 크게 떨어뜨린다.', '0', 'all-opponents', '{"speed": -2}', NULL, 'status', NULL, '벌레'),
	(36, 'Bug Bite', 'Bug', 'Physical', 60, 100, 20, NULL, NULL, '벌레먹음', '물어서 공격한다. 상대가 나무열매를 지니고 있을 때 먹어서 나무열매의 효과를 받을 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
	(37, 'Harden', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '단단해지기', '전신에 힘을 담아 몸을 단단하게 해서 자신의 방어를 올린다.', '0', 'user', '{"defense": 1}', NULL, 'status', NULL, '노말'),
	(38, 'Gust', 'Flying', 'Special', 40, 100, 35, NULL, NULL, '바람일으키기', '날개로 일으킨 격한 바람을 상대에게 부딪쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '비행'),
	(39, 'Supersonic', 'Normal', 'Status', 0, 55, 20, NULL, NULL, '초음파', '특수한 음파를 몸에서 발산하여 상대를 혼란시킨다.', '0', 'selected-pokemon', NULL, 'confusion', 'status', NULL, '노말'),
	(40, 'Confusion', 'Psychic', 'Special', 50, 100, 25, NULL, NULL, '염동력', '약한 염동력을 상대에게 보내어 공격한다. 상대를 혼란시킬 때가 있다.', '0', 'selected-pokemon', NULL, 'confusion', 'special', NULL, '에스퍼'),
	(41, 'Stun Spore', 'Grass', 'Status', 0, 75, 30, NULL, NULL, '저리가루', '저리 가루를 많이 흩뿌려서 상대를 마비 상태로 만든다.', '0', 'selected-pokemon', NULL, 'paralysis', 'status', NULL, '풀'),
	(42, 'Psybeam', 'Psychic', 'Special', 65, 100, 20, NULL, NULL, '환상빔', '이상한 광선을 상대에게 발사하여 공격한다. 혼란시킬 때가 있다.', '0', 'selected-pokemon', NULL, 'confusion', 'special', NULL, '에스퍼'),
	(43, 'Whirlwind', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '날려버리기', '상대를 날려버려서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', '-6', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(44, 'Air Slash', 'Flying', 'Special', 75, 95, 15, NULL, NULL, '에어슬래시', '하늘까지 베어 가르는 공기의 칼날로 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '비행'),
	(45, 'Safeguard', 'Normal', 'Status', 0, 0, 25, NULL, NULL, '신비의부적', '5턴 동안 이상한 힘으로 보호받아 상태 이상이 되지 않는다.', '0', 'users-field', NULL, NULL, 'status', NULL, '노말'),
	(46, 'Bug Buzz', 'Bug', 'Special', 90, 100, 10, NULL, NULL, '벌레의야단법석', '날개의 진동으로 음파를 일으켜서 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '벌레'),
	(47, 'Tailwind', 'Flying', 'Status', 0, 0, 15, NULL, NULL, '순풍', '세차게 불어대는 바람의 소용돌이를 만들어 4턴 동안 같은 편 모두의 스피드를 올린다.', '0', 'users-field', NULL, NULL, 'status', NULL, '비행'),
	(48, 'Rage Powder', 'Bug', 'Status', 0, 0, 20, NULL, NULL, '분노가루', '안절부절못하게 하는 가루를 자신에게 뿌려서 주의를 끈다. 상대의 공격은 모두 자신에게 향한다.', '2', 'user', NULL, NULL, 'status', NULL, '벌레'),
	(49, 'Quiver Dance', 'Bug', 'Status', 0, 0, 20, NULL, NULL, '나비춤', '신비롭고 아름다운 춤을 경쾌하게 춘다. 자신의 특수공격과 특수방어와 스피드를 올린다.', '0', 'user', '{"special-attack": 1, "special-defense": 1, "speed": 1}', NULL, 'status', NULL, '벌레'),
	(50, 'Poison Sting', 'Poison', 'Physical', 15, 100, 35, NULL, NULL, '독침', '독이 있는 침을 상대에게 꿰찔러서 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'physical', NULL, '독'),
	(51, 'Focus Energy', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '기충전', '깊게 숨을 들이마셔 기합을 넣는다. 자신의 공격이 급소에 맞기 쉬워진다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(52, 'Brutal Swing', 'Dark', 'Physical', 60, 100, 20, NULL, NULL, '세차게휘두르기', '자신의 몸을 세차게 휘둘러서 상대에게 데미지를 준다.', '0', 'all-other-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(53, 'X-Scissor', 'Bug', 'Physical', 80, 100, 15, '15', 0, '시저크로스', '낫이나 발톱을 가위처럼 교차시키면서 상대를 베어 가른다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
	(54, 'Toxic Spikes', 'Poison', 'Status', 0, 0, 20, NULL, NULL, '독압정', '상대의 발밑에 독압정을 뿌린다. 교체로 나온 상대 포켓몬에 독을 덮어씌운다.', '0', 'opponents-field', NULL, NULL, 'status', NULL, '독'),
	(55, 'Lunge', 'Bug', 'Physical', 80, 100, 15, NULL, NULL, '덤벼들기', '전력으로 상대에게 덤벼들며 공격한다. 상대의 공격을 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -1}', NULL, 'physical', NULL, '벌레'),
	(56, 'Poison Jab', 'Poison', 'Physical', 80, 100, 20, NULL, NULL, '독찌르기', '독에 물든 촉수나 팔로 상대를 꿰찌른다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'physical', NULL, '독'),
	(57, 'Drill Run', 'Ground', 'Physical', 80, 95, 10, NULL, NULL, '드릴라이너', '드릴처럼 몸을 회전시켜서 상대에게 몸통박치기한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '땅'),
	(58, 'Quick Attack', 'Normal', 'Physical', 40, 100, 30, NULL, NULL, '전광석화', '눈에 보이지 않는 굉장한 속도로 상대에게 돌진한다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(59, 'Twister', 'Dragon', 'Special', 40, 100, 20, NULL, NULL, '회오리', '회오리를 일으켜 상대를 끌어들여 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '드래곤'),
	(60, 'Wing Attack', 'Flying', 'Physical', 60, 100, 35, '35', 0, '날개치기', '크게 펼친 훌륭한 날개를 상대에게 부딪쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(61, 'Agility', 'Psychic', 'Status', 0, 0, 30, NULL, NULL, '고속이동', '힘을 빼고 몸을 가볍게 해서 고속으로 움직인다. 자신의 스피드를 크게 올린다.', '0', 'user', '{"speed": 2}', NULL, 'status', NULL, '에스퍼'),
	(62, 'Feather Dance', 'Flying', 'Status', 0, 100, 15, NULL, NULL, '깃털댄스', '깃털을 흩뿌려 상대의 몸에 휘감는다. 상대의 공격을 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -2}', NULL, 'status', NULL, '비행'),
	(63, 'Hurricane', 'Flying', 'Special', 110, 70, 10, NULL, NULL, '폭풍', '강렬한 바람으로 상대를 둘러싸서 공격한다. 상대를 혼란시킬 때가 있다.', '0', 'selected-pokemon', NULL, 'confusion', 'special', NULL, '비행'),
	(64, 'Brave Bird', 'Flying', 'Physical', 120, 100, 15, NULL, NULL, '브레이브버드', '날개를 접어 저공비행으로 돌격한다. 자신도 상당한 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(65, 'Laser Focus', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '예민해지기', '정신을 집중해서 다음 공격을 반드시 급소에 맞춘다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(66, 'Assurance', 'Dark', 'Physical', 60, 100, 10, NULL, NULL, '승부굳히기', '그 턴에 상대가 이미 데미지를 입었다면 기술의 위력은 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(67, 'Crunch', 'Dark', 'Physical', 80, 100, 15, NULL, NULL, '깨물어부수기', '날카로운 이빨로 상대를 깨물어 부숴서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '악'),
	(68, 'Sucker Punch', 'Dark', 'Physical', 70, 100, 5, NULL, NULL, '기습', '상대보다 먼저 공격할 수 있다. 상대가 쓴 기술이 공격기술이 아니면 실패한다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(69, 'Super Fang', 'Normal', 'Physical', 0, 90, 10, NULL, NULL, '분노의앞니', '날카로운 앞니로 강하게 물어서 공격한다. 상대의 HP는 절반이 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(70, 'Endeavor', 'Normal', 'Physical', 0, 100, 5, NULL, NULL, '죽기살기', '상대의 HP가 자신의 HP와 같아지도록 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(71, 'Scary Face', 'Normal', 'Status', 0, 100, 10, NULL, NULL, '겁나는얼굴', '무서운 얼굴로 노려보고 겁주어 상대의 스피드를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"speed": -2}', NULL, 'status', NULL, '노말'),
	(72, 'Swords Dance', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '칼춤', '싸움의 춤을 격렬하게 추며 기세를 높인다. 자신의 공격을 크게 올린다.', '0', 'user', '{"attack": 2}', NULL, 'status', NULL, '노말'),
