	(81, 'Screech', 'Normal', 'Status', 0, 85, 40, NULL, NULL, '싫은소리', '그만 귀를 막아버리고 싶은 싫은 소리를 내어 상대의 방어를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"defense": -2}', NULL, 'status', NULL, '노말'),
	(82, 'Toxic', 'Poison', 'Status', 0, 90, 10, NULL, NULL, '맹독', '상대를 맹독의 상태로 만든다. 턴이 진행될수록 독의 데미지가 증가한다.', '0', 'selected-pokemon', NULL, 'poison', 'status', NULL, '독'),
	(83, 'Leech Life', 'Bug', 'Physical', 80, 100, 10, NULL, NULL, '흡혈', '피를 빨아서 상대를 공격한다. 준 데미지의 절반을 HP로 회복한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
	(84, 'Haze', 'Ice', 'Status', 0, 0, 30, NULL, NULL, '흑안개', '흑안개를 뿜어 배틀에 참가 중인 포켓몬 전원의 능력 변화를 원래대로 돌린다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '얼음'),
