	(125, 'Mystical Fire', 'Fire', 'Special', 75, 100, 10, NULL, NULL, '매지컬플레임', '입에서 내뱉는 아주 뜨거운 불꽃으로 공격한다. 상대의 특수공격을 떨어뜨린다.', '0', 'selected-pokemon', '{"special-attack": -1}', NULL, 'special', NULL, '불꽃'),
	(126, 'Moonblast', 'Fairy', 'Special', 95, 100, 15, NULL, NULL, '문포스', '달의 파워를 빌려서 상대를 공격한다. 상대의 특수공격을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-attack": -1}', NULL, 'special', NULL, '페어리'),
	(127, 'Disable', 'Normal', 'Status', 0, 100, 20, NULL, NULL, '사슬묶기', '상대의 움직임을 막아 바로 전에 쓴 기술을 4턴 동안 사용할 수 없게 만든다.', '0', 'selected-pokemon', NULL, 'disable', 'status', NULL, '노말'),
	(128, 'Spite', 'Ghost', 'Status', 0, 100, 10, NULL, NULL, '원한', '상대가 마지막으로 사용한 기술에 원한을 품어 그 기술의 PP를 4만큼 줄인다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '고스트'),
	(129, 'Incinerate', 'Fire', 'Special', 60, 100, 15, NULL, NULL, '불태우기', '불꽃으로 상대를 공격한다. 상대가 나무열매 등을 지니고 있을 때 불태워서 쓸 수 없게 만든다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '불꽃'),
