	(131, 'Will-O-Wisp', 'Fire', 'Status', 0, 85, 15, NULL, NULL, '도깨비불', '으스스하고 괴상한 불꽃을 쏘아 상대를 화상 상태로 만든다.', '0', 'selected-pokemon', NULL, 'burn', 'status', NULL, '불꽃'),
	(132, 'Extrasensory', 'Psychic', 'Special', 80, 100, 20, NULL, NULL, '신통력', '보이지 않는 이상한 힘을 보내어 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
