	(142, 'Wish', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '희망사항', '다음 턴에 자신의 HP를 최대 HP의 절반만큼 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(143, 'Perish Song', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '멸망의노래', '노래를 들은 포켓몬은 3턴이 지나면 기절한다. 교체되면 효과가 없어진다.', '0', 'all-pokemon', NULL, 'perish-song', 'status', NULL, '노말'),
	(144, 'Absorb', 'Grass', 'Special', 20, 100, 25, NULL, NULL, '흡수', '양분을 흡수하여 공격한다. 상대에게 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '풀'),
