	(169, 'Aqua Tail', 'Water', 'Physical', 90, 90, 10, '10', 0, '아쿠아테일', '세차게 날뛰는 거친 파도와 같이 큰 꼬리를 흔들어서 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(170, 'Soak', 'Water', 'Status', 0, 100, 20, NULL, NULL, '물붓기', '많은 물을 끼얹어서 상대를 물타입으로 바꾼다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '물'),
