	(182, 'Rage Fist', 'Ghost', 'Physical', 50, 100, 10, NULL, NULL, NULL, NULL, '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(183, 'Howl', 'Normal', 'Status', 0, 0, 40, NULL, NULL, '멀리짖음', '큰 소리로 짖고 기합을 높여 자신의 공격을 올린다.', '0', 'user-and-allies', '{"attack": 1}', NULL, 'status', NULL, '노말'),
	(184, 'Flame Wheel', 'Fire', 'Physical', 60, 100, 25, NULL, NULL, '화염자동차', '불꽃을 둘러 상대에게 돌진하여 공격한다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'physical', NULL, '불꽃'),
	(185, 'Retaliate', 'Normal', 'Physical', 70, 100, 5, NULL, NULL, '원수갚기', '쓰러진 같은 편의 원수를 갚는다. 앞 턴에서 같은 편이 쓰러졌다면 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(186, 'Roar', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '울부짖기', '상대를 도망가게 해서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', '-6', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(187, 'Reversal', 'Fighting', 'Physical', 0, 100, 15, NULL, NULL, '기사회생', '힘을 쥐어짜서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(188, 'Pound', 'Normal', 'Physical', 40, 100, 35, '35', 0, '막치기', '긴 꼬리나 손 등을 사용하여 상대를 때려서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(189, 'Mud Shot', 'Ground', 'Special', 55, 95, 15, NULL, NULL, '머드숏', '진흙 덩어리를 상대에게 내던져서 공격한다. 동시에 상대의 스피드를 떨어뜨린다.', '0', 'selected-pokemon', '{"speed": -1}', NULL, 'special', NULL, '땅'),
	(190, 'Rain Dance', 'Water', 'Status', 0, 0, 5, NULL, NULL, '비바라기', '5턴 동안 비를 내리게 하여 물타입 기술의 위력을 올린다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '물'),
	(191, 'Belly Drum', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '배북', '자신의 HP를 최대 HP의 절반만큼 감소시켜 자신의 공격을 최대로 올린다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(192, 'Teleport', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '순간이동', '야생 포켓몬과 배틀을 그만둔다. 마지막에 들어갔던 포켓몬센터가 있는 도시에도 갈 수 있다.', '-6', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(193, 'Reflect', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '리플렉터', '5턴 동안 이상한 장막으로 상대로부터 받는 물리공격의 데미지를 약하게 한다.', '0', 'users-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(194, 'Psycho Cut', 'Psychic', 'Physical', 70, 100, 20, NULL, NULL, '사이코커터', '실체화시킨 마음의 칼날로 상대를 베어 가른다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '에스퍼'),
	(195, 'Recover', 'Normal', 'Status', 0, 0, 5, NULL, NULL, 'HP회복', '세포를 재생시켜 자신의 최대 HP의 절반만큼 HP를 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(196, 'Psyshock', 'Psychic', 'Special', 80, 100, 10, NULL, NULL, '사이코쇼크', '이상한 염력파를 실체화하여 상대를 공격한다. 물리적인 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(197, 'Future Sight', 'Psychic', 'Special', 120, 100, 10, NULL, NULL, '미래예지', '기술을 사용한 2턴 뒤에 상대에게 염동력의 덩어리를 보내어 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(198, 'Calm Mind', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '명상', '조용히 정신을 통일하고 마음을 가라앉혀서 자신의 특수공격과 특수방어를 올린다.', '0', 'user', '{"special-attack": 1, "special-defense": 1}', NULL, 'status', NULL, '에스퍼'),
	(199, 'Power-Up Punch', 'Fighting', 'Physical', 40, 100, 20, NULL, NULL, '그로우펀치', '반복하여 때리면 점점 주먹이 단단해진다. 상대를 때리면 공격이 오른다.', '0', 'selected-pokemon', '{"attack": 1}', NULL, 'physical', NULL, '격투'),
	(200, 'Bullet Punch', 'Steel', 'Physical', 40, 100, 30, NULL, NULL, '불릿펀치', '탄환처럼 빠르고 단단한 펀치를 상대에게 날린다. 반드시 선제공격을 할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(201, 'Bulk Up', 'Fighting', 'Status', 0, 0, 20, NULL, NULL, '벌크업', '몸에 힘을 담아 근육을 두껍게 해서 자신의 공격과 방어를 올린다.', '0', 'user', '{"attack": 1, "defense": 1}', NULL, 'status', NULL, '격투'),
	(202, 'Detect', 'Fighting', 'Status', 0, 0, 5, NULL, NULL, '판별', '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', '4', 'user', NULL, NULL, 'status', NULL, '격투'),
	(203, 'Heavy Slam', 'Steel', 'Physical', 0, 100, 10, NULL, NULL, '헤비봄버', '무거운 몸으로 상대에게 부딪쳐 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(204, 'Infestation', 'Bug', 'Special', 20, 100, 20, NULL, NULL, '엉겨붙기', '4-5턴 동안 상대에게 엉겨 붙어서 공격한다. 그동안 상대는 도망갈 수 없다.', '0', 'selected-pokemon', NULL, 'trap', 'special', NULL, '벌레'),
	(205, 'Power Whip', 'Grass', 'Physical', 120, 85, 10, '10', 0, '파워휩', '덩굴이나 촉수를 세차게 흔들어 상대를 힘껏 쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(206, 'Leaf Storm', 'Grass', 'Special', 130, 90, 5, NULL, NULL, '리프스톰', '뾰족한 잎사귀로 상대에게 바람을 일으킨다. 사용하면 반동으로 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '풀'),
	(207, 'Wrap', 'Normal', 'Physical', 15, 90, 20, NULL, NULL, '김밥말이', '긴 몸이나 덩굴 등을 사용해 4-5턴 동안 상대를 휘감아 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'physical', NULL, '노말'),
	(208, 'Hex', 'Ghost', 'Special', 65, 100, 10, NULL, NULL, '병상첨병', '엎친 데 덮친 격으로 공격한다. 상태 이상인 상대에게 큰 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '고스트'),
	(209, 'Acid Armor', 'Poison', 'Status', 0, 0, 20, NULL, NULL, '녹기', '세포의 변화로 액체가 되어 자신의 방어를 크게 올린다.', '0', 'user', '{"defense": 2}', NULL, 'status', NULL, '독'),
	(210, 'Surf', 'Water', 'Special', 90, 100, 15, NULL, NULL, '파도타기', '큰 파도로 자신의 주위에 있는 포켓몬을 공격한다. 물 위도 헤엄쳐서 나아간다.', '0', 'all-other-pokemon', NULL, NULL, 'special', NULL, '물'),
	(211, 'Reflect Type', 'Normal', 'Status', 0, 0, 15, NULL, NULL, '미러타입', '상대의 타입을 반사해서 자신도 똑같은 타입이 된다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(212, 'Rock Polish', 'Rock', 'Status', 0, 0, 20, NULL, NULL, '록커트', '자신의 몸을 갈아 공기의 저항을 적게 한다. 스피드를 크게 올릴 수 있다.', '0', 'user', '{"speed": 2}', NULL, 'status', NULL, '바위'),
	(213, 'Smack Down', 'Rock', 'Physical', 50, 100, 15, NULL, NULL, '떨어뜨리기', '돌이나 구슬을 던져서 날고 있는 상대를 공격한다. 맞은 상대는 땅에 떨어진다.', '0', 'selected-pokemon', NULL, 'unknown', 'physical', NULL, '바위'),
	(214, 'Self-Destruct', 'Normal', 'Physical', 200, 100, 5, NULL, NULL, '자폭', '폭발을 일으켜서 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서 기절하게 된다.', '0', 'all-other-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(215, 'Stealth Rock', 'Rock', 'Status', 0, 0, 20, NULL, NULL, '스텔스록', '상대의 주위에 무수한 바위를 띄워 교체해서 나온 상대 포켓몬에게 데미지를 준다.', '0', 'opponents-field', NULL, NULL, 'status', NULL, '바위'),
	(216, 'Rock Blast', 'Rock', 'Physical', 25, 90, 10, NULL, NULL, '락블레스트', '단단한 암석을 상대에게 발사하여 공격한다. 2-5회 동안 연속으로 쓴다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '바위'),
	(217, 'Explosion', 'Normal', 'Physical', 250, 100, 5, NULL, NULL, '대폭발', '큰 폭발로 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서는 기절한다.', '0', 'all-other-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(218, 'Stone Edge', 'Rock', 'Physical', 100, 80, 5, NULL, NULL, '스톤에지', '뾰족한 바위를 상대에게 꿰찔러서 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '바위'),
	(219, 'Double Hit', 'Normal', 'Physical', 35, 90, 10, NULL, NULL, '더블어택', '꼬리 등을 써서 상대를 때려 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(220, 'Curse', 'Ghost', 'Status', 0, 0, 10, NULL, NULL, '저주', '기술을 쓰는 포켓몬이 고스트타입일 때와 그 이외의 타입일 때는 효과가 다르다.', '0', 'specific-move', NULL, NULL, 'status', NULL, '고스트'),
	(221, 'Headbutt', 'Normal', 'Physical', 70, 100, 15, NULL, NULL, '박치기', '머리를 내밀어 곧장 돌진하여 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(222, 'Electro Ball', 'Electric', 'Special', 0, 100, 10, NULL, NULL, '일렉트릭볼', '전기 덩어리를 상대에게 부딪쳐서 공격한다. 상대보다 스피드가 빠를수록 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '전기'),
	(223, 'Magnet Rise', 'Electric', 'Status', 0, 0, 10, NULL, NULL, '전자부유', '전기로 만든 자력의 힘으로 허공에 뜬다. 5턴 동안 부유할 수 있다.', '0', 'user', NULL, NULL, 'status', NULL, '전기'),
	(224, 'Flash Cannon', 'Steel', 'Special', 80, 100, 10, NULL, NULL, '러스터캐논', '몸의 빛을 한곳에 모아서 힘을 쏜다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '강철'),
	(225, 'Discharge', 'Electric', 'Special', 80, 100, 15, NULL, NULL, '방전', '눈부신 전격으로 자신의 주위에 있는 포켓몬을 공격한다. 마비 상태로 만들 때가 있다.', '0', 'all-other-pokemon', NULL, 'paralysis', 'special', NULL, '전기'),
	(226, 'Metal Sound', 'Steel', 'Status', 0, 85, 40, NULL, NULL, '금속음', '금속을 긁을 때 나는 듯한 싫은 소리를 들려준다. 상대의 특수방어를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -2}', NULL, 'status', NULL, '강철'),
	(227, 'Lock-On', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '록온', '조준을 잘 맞춰 다음 공격이 반드시 상대에게 명중하도록 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(228, 'Zap Cannon', 'Electric', 'Special', 120, 50, 5, NULL, NULL, '전자포', '대포처럼 전기를 발사해서 공격한다. 상대를 마비 상태로 만든다.', '0', 'selected-pokemon', NULL, 'paralysis', 'special', NULL, '전기'),
	(229, 'Electric Terrain', 'Electric', 'Status', 0, 0, 10, NULL, NULL, '일렉트릭필드', '5턴 동안 발밑을 일렉트릭필드로 만든다. 땅에 있는 포켓몬은 잠들지 않게 된다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '전기'),
	(230, 'Steel Wing', 'Steel', 'Physical', 70, 90, 25, NULL, NULL, '강철날개', '단단한 날개를 상대에게 부딪쳐서 공격한다. 자신의 방어가 올라갈 때가 있다.', '0', 'selected-pokemon', '{"defense": 1}', NULL, 'physical', NULL, '강철'),
	(231, 'False Swipe', 'Normal', 'Physical', 40, 100, 40, NULL, NULL, '칼등치기', '상대의 HP가 반드시 1만큼 남도록 조절하여 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(232, 'Leaf Blade', 'Grass', 'Physical', 90, 100, 15, NULL, NULL, '리프블레이드', '잎사귀를 칼처럼 이용해 상대를 베어 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(233, 'Uproar', 'Normal', 'Special', 90, 100, 10, NULL, NULL, '소란피기', '3턴 동안 소란 피워 공격한다. 그 동안은 아무도 잠들지 않게 된다.', '0', 'random-opponent', NULL, NULL, 'special', NULL, '노말'),
	(234, 'Acupressure', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '경혈찌르기', '경혈을 눌러 몸을 활성화시킨다. 능력 중 하나를 크게 올린다.', '0', 'user-or-ally', NULL, NULL, 'status', NULL, '노말'),
	(235, 'Thrash', 'Normal', 'Physical', 120, 100, 10, NULL, NULL, '난동부리기', '2-3턴 동안 마구 난동 부려서 상대를 공격한다. 난동 부린 뒤에는 혼란에 빠진다.', '0', 'random-opponent', NULL, NULL, 'physical', NULL, '노말'),
	(236, 'Encore', 'Normal', 'Status', 0, 100, 5, NULL, NULL, '앵콜', '상대가 마지막으로 사용한 기술을 3턴 동안 계속 쓰게 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(237, 'Ice Shard', 'Ice', 'Physical', 40, 100, 30, NULL, NULL, '얼음뭉치', '얼음 덩어리를 순식간에 만들어 상대에게 빠르게 쏜다. 반드시 선제공격을 할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '얼음'),
	(238, 'Rest', 'Psychic', 'Status', 0, 0, 5, NULL, NULL, '잠자기', '2턴 동안 계속 잠잔다. 자신의 HP와 상태 이상을 모두 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(239, 'Aurora Beam', 'Ice', 'Special', 65, 100, 20, NULL, NULL, '오로라빔', '무지개색의 빔을 상대에게 발사하여 공격한다. 공격을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"attack": -1}', NULL, 'special', NULL, '얼음'),
	(240, 'Brine', 'Water', 'Special', 65, 100, 10, NULL, NULL, '소금물', '상대가 HP의 절반 정도 상처를 입고 있으면 기술의 위력이 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '물'),
	(241, 'Dive', 'Water', 'Physical', 80, 100, 10, NULL, NULL, '다이빙', '1턴째에 잠수했다가 2턴째에 떠올라 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(242, 'Ice Beam', 'Ice', 'Special', 90, 100, 10, NULL, NULL, '냉동빔', '냉동빔을 상대에게 발사하여 공격한다. 얼음 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'freeze', 'special', NULL, '얼음'),
	(243, 'Snowscape', 'Ice', 'Status', 0, 0, 10, NULL, NULL, NULL, NULL, '0', 'entire-field', NULL, NULL, 'status', NULL, '얼음'),
	(244, 'Poison Gas', 'Poison', 'Status', 0, 90, 40, NULL, NULL, '독가스', '독가스를 상대의 얼굴에 내뿜어 독 상태로 만든다.', '0', 'all-opponents', NULL, 'poison', 'status', NULL, '독'),
	(245, 'Sludge', 'Poison', 'Special', 65, 100, 20, NULL, NULL, '오물공격', '더러운 오물을 상대에게 내던져서 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(246, 'Minimize', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '작아지기', '몸을 축소하여 작게 보임으로써 자신의 회피율을 크게 올린다.', '0', 'user', '{"evasion": 2}', NULL, 'status', NULL, '노말'),
	(247, 'Sludge Bomb', 'Poison', 'Special', 90, 100, 10, NULL, NULL, '오물폭탄', '더러운 오물을 상대에게 내던져서 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(248, 'Belch', 'Poison', 'Special', 120, 90, 10, NULL, NULL, '트림', '상대를 향해 트림을 하여 데미지를 준다. 나무열매를 먹지 않으면 쓸 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '독'),
	(249, 'Memento', 'Dark', 'Status', 0, 100, 10, NULL, NULL, '추억의선물', '자신은 기절하게 되지만 그 대신 상대의 공격과 특수공격을 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -2, "special-attack": -2}', NULL, 'status', NULL, '악'),
	(250, 'Withdraw', 'Water', 'Status', 0, 0, 40, NULL, NULL, '껍질에숨기', '껍질에 숨어 몸을 보호하여 자신의 방어를 올린다.', '0', 'user', '{"defense": 1}', NULL, 'status', NULL, '물'),
	(251, 'Whirlpool', 'Water', 'Special', 35, 85, 15, NULL, NULL, '바다회오리', '세차게 소용돌이치는 물속에 4-5턴 동안 상대를 가두어 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'special', NULL, '물'),
	(252, 'Protect', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '방어', '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', '4', 'user', NULL, NULL, 'status', NULL, '노말'),
	(253, 'Razor Shell', 'Water', 'Physical', 75, 95, 10, NULL, NULL, '셸블레이드', '날카로운 조개껍질로 베어 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '물'),
	(254, 'Shell Smash', 'Normal', 'Status', 0, 0, 15, NULL, NULL, '껍질깨기', '껍질을 깨서 자신의 방어와 특수방어를 떨어뜨리지만 공격과 특수공격, 스피드를 크게 올린다.', '0', 'user', '{"defense": -1, "special-defense": -1, "attack": 2, "special-attack": 2, "speed": 2}', NULL, 'status', NULL, '노말'),
	(255, 'Icicle Crash', 'Ice', 'Physical', 85, 90, 10, NULL, NULL, '고드름떨구기', '큰 고드름을 격렬하게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '얼음'),
	(256, 'Spikes', 'Ground', 'Status', 0, 0, 20, NULL, NULL, '압정뿌리기', '상대의 발밑에 압정을 뿌린다. 교체된 상대 포켓몬에게 데미지를 준다.', '0', 'opponents-field', NULL, NULL, 'status', NULL, '땅'),
	(257, 'Lick', 'Ghost', 'Physical', 30, 100, 30, NULL, NULL, '핥기', '긴 혀로 상대를 핥아서 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '고스트'),
	(258, 'Shadow Sneak', 'Ghost', 'Physical', 40, 100, 30, NULL, NULL, '야습', '그림자를 늘려 상대의 배후에서 공격한다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(259, 'Dark Pulse', 'Dark', 'Special', 80, 100, 15, NULL, NULL, '악의파동', '몸에서 악의로 가득한 무서운 오라를 발한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '악'),
	(260, 'Shadow Ball', 'Ghost', 'Special', 80, 100, 15, NULL, NULL, '섀도볼', '까만 그림자의 덩어리를 내던져서 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '고스트'),
	(261, 'Shadow Claw', 'Ghost', 'Physical', 70, 100, 15, NULL, NULL, '섀도크루', '그림자로 만든 날카로운 발톱으로 상대를 베어 가른다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(262, 'Phantom Force', 'Ghost', 'Physical', 90, 100, 10, NULL, NULL, '고스트다이브', '1턴째에 어디론가 사라져서 2턴째에 상대를 공격한다. 기술 방어를 무시하고 공격할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(263, 'Rock Slide', 'Rock', 'Physical', 75, 90, 10, NULL, NULL, '스톤샤워', '큰 바위를 세차게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'all-opponents', NULL, NULL, 'physical', NULL, '바위'),
	(264, 'Breaking Swipe', 'Dragon', 'Physical', 60, 100, 15, NULL, NULL, '와이드브레이커', '강인한 꼬리를 세차게 휘둘러서 상대를 공격한다. 상대의 공격을 떨어뜨린다.', '0', 'all-opponents', '{"attack": -1}', NULL, 'physical', NULL, '드래곤'),
	(265, 'Iron Tail', 'Steel', 'Physical', 100, 75, 15, NULL, NULL, '아이언테일', '단단한 꼬리로 상대를 힘껏 쳐서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '강철'),
	(266, 'Head Smash', 'Rock', 'Physical', 150, 80, 5, NULL, NULL, '양날박치기', '목숨을 걸고 혼신의 힘으로 상대에게 박치기를 한다. 자신도 굉장한 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '바위'),
	(267, 'Swagger', 'Normal', 'Status', 0, 85, 15, NULL, NULL, '뽐내기', '상대를 화내게 해서 혼란시킨다. 분노로 상대의 공격은 크게 올라가 버린다.', '0', 'selected-pokemon', '{"attack": 2}', 'confusion', 'status', NULL, '노말'),
	(268, 'Switcheroo', 'Dark', 'Status', 0, 100, 10, NULL, NULL, '바꿔치기', '눈에 보이지 않는 속도로 자신과 상대가 지닌 물건을 교환한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '악'),
	(269, 'Stomp', 'Normal', 'Physical', 65, 100, 20, NULL, NULL, '짓밟기', '큰 발로 상대를 짓밟아서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(270, 'Flail', 'Normal', 'Physical', 0, 100, 15, NULL, NULL, '바둥바둥', '바둥바둥 난동 부려서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(271, 'Slam', 'Normal', 'Physical', 80, 75, 20, '20', 0, '힘껏치기', '긴 꼬리나 덩굴 등을 사용해 상대를 힘껏 쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(272, 'Crabhammer', 'Water', 'Physical', 100, 90, 10, NULL, NULL, '찝게햄머', '큰 집게를 상대에게 내리쳐서 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(273, 'Guillotine', 'Normal', 'Physical', 0, 30, 5, NULL, NULL, '가위자르기', '큰 집게로 상대를 베어 갈라 공격한다. 맞으면 일격에 기절한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(274, 'Hammer Arm', 'Fighting', 'Physical', 100, 90, 10, NULL, NULL, '암해머', '강하고 무거운 주먹을 휘둘러 데미지를 준다. 자신의 스피드가 떨어진다.', '0', 'selected-pokemon', '{"speed": -1}', NULL, 'physical', NULL, '격투'),
	(275, 'Wide Guard', 'Rock', 'Status', 0, 0, 10, NULL, NULL, '와이드가드', '같은 편 전원에게 향하는 공격을 1턴 동안 막는다. ', '3', 'users-field', NULL, NULL, 'status', NULL, '바위'),
	(276, 'Eerie Impulse', 'Electric', 'Status', 0, 100, 15, NULL, NULL, '괴전파', '몸에서 괴전파를 내어 상대에게 쏨으로써 특수공격을 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'status', NULL, '전기'),
	(277, 'Charge Beam', 'Electric', 'Special', 50, 90, 10, NULL, NULL, '차지빔', '전격의 다발을 상대에게 발사한다. 전기를 모아서 자신의 특수공격을 올릴 때가 있다.', '0', 'selected-pokemon', '{"special-attack": 1}', NULL, 'special', NULL, '전기'),
	(278, 'Mirror Coat', 'Psychic', 'Special', 0, 100, 20, NULL, NULL, '미러코트', '상대에게 받은 특수공격의 데미지를 2배로 만들어 그 상대에게 돌려준다.', '-5', 'specific-move', NULL, NULL, 'special', NULL, '에스퍼'),
	(279, 'Magnetic Flux', 'Electric', 'Status', 0, 0, 20, NULL, NULL, '자기장조작', '자기장 조작으로 인해 특성 플러스와 마이너스의 방어, 특수방어가 오른다.', '0', 'user-and-allies', '{"defense": 1, "special-defense": 1}', NULL, 'status', NULL, '전기'),
	(280, 'Bullet Seed', 'Grass', 'Physical', 25, 100, 30, NULL, NULL, '기관총', '씨앗을 기세 좋게 상대에게 발사하여 공격한다. 2-5회 동안 연속으로 쓴다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(281, 'Worry Seed', 'Grass', 'Status', 0, 100, 10, NULL, NULL, '고민씨', '마음을 괴롭히는 씨앗을 심는다. 상대를 잠잘 수 없게 해서 특성을 불면으로 만든다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '풀'),
	(282, 'Seed Bomb', 'Grass', 'Physical', 80, 100, 15, '15', 0, '씨폭탄', '단단한 껍질을 가지고 있는 큰 씨앗을 힘껏 내던져 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(283, 'Wood Hammer', 'Grass', 'Physical', 120, 100, 15, NULL, NULL, '우드해머', '단단한 몸통을 상대에게 부딪쳐서 공격한다. 자신도 상당한 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(284, 'Bonemerang', 'Ground', 'Physical', 50, 90, 10, NULL, NULL, '뼈다귀부메랑', '손에 들고 있는 뼈를 상대에게 날려서 날아갈 때와 돌아올 때 2회 연속 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '땅'),
	(285, 'Fake Out', 'Normal', 'Physical', 40, 100, 10, NULL, NULL, '속이다', '선제공격으로 상대를 풀죽게 한다. 배틀에 나가서 바로 쓰지 않으면 성공할 수 없다.', '3', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(286, 'Low Kick', 'Fighting', 'Physical', 0, 100, 20, NULL, NULL, '안다리걸기', '발을 강하게 걸고 상대를 넘어뜨려 공격한다. 상대가 무거울수록 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(287, 'Endure', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '버티기', '공격을 받아도 HP를 반드시 1만큼은 남긴다. 연속으로 쓰면 실패하기 쉽다.', '4', 'user', NULL, NULL, 'status', NULL, '노말'),
	(288, 'Blaze Kick', 'Fire', 'Physical', 85, 90, 10, NULL, NULL, '브레이즈킥', '공격한 상대를 화상 상태로 만들 때가 있다. 급소에도 맞기 쉽다.', '0', 'selected-pokemon', NULL, 'burn', 'physical', NULL, '불꽃'),
	(289, 'Feint', 'Normal', 'Physical', 30, 100, 10, NULL, NULL, '페인트', '방어나 판별을 하고 있는 상대에게 공격할 수 있다. 방어 효과를 해제시킨다.', '2', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(290, 'Mega Kick', 'Normal', 'Physical', 120, 75, 5, '5', 0, '메가톤킥', '굉장한 힘을 담은 킥으로 상대를 걷어차서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(291, 'High Jump Kick', 'Fighting', 'Physical', 130, 90, 10, NULL, NULL, '무릎차기', '점프해서 무릎차기로 상대를 공격한다. 빗나가면 자신이 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(292, 'Axe Kick', 'Fighting', 'Physical', 120, 90, 10, NULL, NULL, NULL, NULL, '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(293, 'Mach Punch', 'Fighting', 'Physical', 40, 100, 30, NULL, NULL, '마하펀치', '눈에 보이지 않는 굉장한 속도로 펀치를 날린다. 반드시 선제공격을 할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(294, 'Vacuum Wave', 'Fighting', 'Special', 40, 100, 30, NULL, NULL, '진공파', '주먹을 흔들어 진공의 파도를 일으킨다. 반드시 선제공격을 할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'special', NULL, '격투'),
	(295, 'Quick Guard', 'Fighting', 'Status', 0, 0, 15, NULL, NULL, '퍼스트가드', '자신과 같은 편을 상대의 선제공격으로부터 지킨다. ', '3', 'users-field', NULL, NULL, 'status', NULL, '격투'),
	(296, 'Fire Punch', 'Fire', 'Physical', 75, 100, 15, NULL, NULL, '불꽃펀치', '불꽃을 담은 펀치로 상대를 공격한다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'physical', NULL, '불꽃'),
	(297, 'Ice Punch', 'Ice', 'Physical', 75, 100, 15, NULL, NULL, '냉동펀치', '냉기를 담은 펀치로 상대를 공격한다. 얼음 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'freeze', 'physical', NULL, '얼음'),
	(298, 'Thunder Punch', 'Electric', 'Physical', 75, 100, 15, NULL, NULL, '번개펀치', '전격을 담은 펀치로 상대를 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '전기'),
	(299, 'Mega Punch', 'Normal', 'Physical', 80, 85, 20, '20', 0, '메가톤펀치', '힘을 담은 펀치로 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(300, 'Counter', 'Fighting', 'Physical', 0, 100, 20, NULL, NULL, '카운터', '상대로부터 받은 물리공격의 데미지를 2배로 만들어 같은 상대에게 돌려준다.', '-5', 'specific-move', NULL, NULL, 'physical', NULL, '격투'),
	(301, 'Focus Punch', 'Fighting', 'Physical', 150, 100, 20, NULL, NULL, '힘껏펀치', '정신력을 높여 펀치를 날린다. 기술을 쓰기 전에 공격을 받으면 실패한다.', '-3', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(302, 'Giga Impact', 'Normal', 'Physical', 150, 90, 5, NULL, NULL, '기가임팩트', '가진 힘을 모두 사용해서 상대에게 돌격한다. 다음 턴은 움직일 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(303, 'Smog', 'Poison', 'Special', 30, 70, 20, NULL, NULL, '스모그', '더러운 가스를 상대에게 내뿜어 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(304, 'Clear Smog', 'Poison', 'Special', 50, 0, 15, NULL, NULL, '클리어스모그', '특수한 진흙 덩어리를 상대에게 내던져서 공격한다. 능력 변화를 원래대로 돌린다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '독'),
	(305, 'Destiny Bond', 'Ghost', 'Status', 0, 0, 5, NULL, NULL, '길동무', '기술을 쓴 뒤 공격을 받아 기절했을 때 길동무의 대상도 기절하게 한다.', '0', 'user', NULL, NULL, 'status', NULL, '고스트'),
	(306, 'Heat Wave', 'Fire', 'Special', 95, 90, 10, NULL, NULL, '열풍', '뜨거운 숨결을 상대에게 내뿜어 공격한다. 화상 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'burn', 'special', NULL, '불꽃'),
	(307, 'Horn Drill', 'Normal', 'Physical', 0, 30, 5, NULL, NULL, '뿔드릴', '회전하는 뿔을 상대에게 꿰찔러서 공격한다. 맞으면 일격에 기절한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(308, 'Copycat', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '흉내쟁이', '직전에 나온 기술을 흉내 내어 같은 기술을 쓴다. 기술이 나오지 않았으면 실패한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(309, 'Covet', 'Normal', 'Physical', 60, 100, 25, NULL, NULL, '탐내다', '귀엽게 애교부리며 상대에게 다가가 지니고 있는 도구를 뺏는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(310, 'Sweet Kiss', 'Fairy', 'Status', 0, 75, 10, NULL, NULL, '천사의키스', '천사처럼 귀엽게 키스하여 상대를 혼란시킨다.', '0', 'selected-pokemon', NULL, 'confusion', 'status', NULL, '페어리'),
	(311, 'Echoed Voice', 'Normal', 'Special', 40, 100, 15, NULL, NULL, '에코보이스', '울리는 목소리로 상대를 공격한다. 매 턴 누군가 기술을 계속해서 쓰면 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '노말'),
	(312, 'Life Dew', 'Water', 'Status', 0, 0, 10, NULL, NULL, '생명의물방울', '신비한 물을 흩뿌려서 자신과 배틀에 나와 있는 같은 편의 HP를 회복한다.', '0', 'user-and-allies', NULL, NULL, 'status', NULL, '물'),
	(313, 'Fling', 'Dark', 'Physical', 0, 100, 10, NULL, NULL, '내던지기', '지니게 한 도구를 재빠르게 내던져서 공격한다. 도구에 따라 위력과 효과가 바뀐다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(314, 'Heal Pulse', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '치유파동', '치유파동을 날려서 최대 HP의 절반만큼 상대의 HP를 회복한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(315, 'Soft-Boiled', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '알낳기', '자신의 최대 HP 절반을 회복한다. 동료에게 HP를 나누어 줄 수도 있다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(316, 'Last Resort', 'Normal', 'Physical', 140, 100, 5, NULL, NULL, '뒀다쓰기', '배틀 중에 기억하고 있는 기술을 모두 사용하면 그때부터 쓸 수 있는 필살기이다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(317, 'Healing Wish', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '치유소원', '자신은 기절하지만 교대하여 나오는 포켓몬의 상태 이상과 HP를 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(318, 'Acid Spray', 'Poison', 'Special', 40, 100, 20, NULL, NULL, '애시드봄', '상대를 녹이는 액체를 토해내서 공격한다. 상대의 특수방어를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -2}', NULL, 'special', NULL, '독'),
	(319, 'Ancient Power', 'Rock', 'Special', 60, 100, 5, NULL, NULL, '원시의힘', '원시의 힘으로 공격한다. 자신의 모든 능력이 오를 때가 있다.', '0', 'selected-pokemon', '{"attack": 1, "defense": 1, "special-attack": 1, "special-defense": 1, "speed": 1}', NULL, 'special', NULL, '바위'),
	(320, 'Dragon Pulse', 'Dragon', 'Special', 85, 100, 10, '10', 0, '용의파동', '큰 입으로 충격파를 일으켜서 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '드래곤'),
	(321, 'Dragon Dance', 'Dragon', 'Status', 0, 0, 20, NULL, NULL, '용의춤', '신비롭고 힘센 춤을 격렬하게 춘다. 자신의 공격과 스피드를 올린다.', '0', 'user', '{"attack": 1, "speed": 1}', NULL, 'status', NULL, '드래곤'),
	(322, 'Waterfall', 'Water', 'Physical', 80, 100, 15, NULL, NULL, '폭포오르기', '굉장한 기세로 상대에게 돌진한다. 상대를 풀죽게 만들 때가 있다. 폭포도 거슬러 올라갈 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(323, 'Power Gem', 'Rock', 'Special', 80, 100, 20, '20', 0, '파워젬', '보석처럼 반짝이는 빛을 발사하여 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '바위'),
	(324, 'Dream Eater', 'Psychic', 'Special', 100, 100, 15, NULL, NULL, '꿈먹기', '잠자고 있는 상대의 꿈을 먹어 공격한다. 데미지의 절반을 HP로 회복한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(325, 'Double Team', 'Normal', 'Status', 0, 0, 15, NULL, NULL, '그림자분신', '재빠른 움직임으로 분신을 만들어 상대를 혼란시켜 회피율을 올린다.', '0', 'user', '{"evasion": 1}', NULL, 'status', NULL, '노말'),
	(326, 'Powder Snow', 'Ice', 'Special', 40, 100, 25, NULL, NULL, '눈싸라기', '차가운 가랑눈을 상대에게 내뿜어 공격한다. 얼음 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'freeze', 'special', NULL, '얼음'),
	(327, 'Lovely Kiss', 'Normal', 'Status', 0, 75, 10, NULL, NULL, '악마의키스', '무서운 얼굴로 키스한다. 상대를 잠듦 상태로 만든다.', '0', 'selected-pokemon', NULL, 'sleep', 'status', NULL, '노말'),
	(328, 'Mean Look', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '검은눈빛', '빨려 들어갈 것 같은 까만 눈빛으로 가만히 응시하여 상대를 배틀에서 도망갈 수 없게 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(329, 'Blizzard', 'Ice', 'Special', 110, 70, 5, NULL, NULL, '눈보라', '세찬 눈보라를 상대에게 내뿜어 공격한다. 얼음 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'freeze', 'special', NULL, '얼음'),
	(330, 'Shock Wave', 'Electric', 'Special', 60, 0, 20, NULL, NULL, '전격파', '전격을 재빠르게 상대에게 날린다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '전기'),
	(331, 'Lava Plume', 'Fire', 'Special', 80, 100, 15, NULL, NULL, '분연', '새빨간 불꽃으로 자신의 주위에 있는 포켓몬을 공격한다. 화상 상태로 만들 때가 있다.', '0', 'all-other-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(332, 'Sunny Day', 'Fire', 'Status', 0, 0, 5, NULL, NULL, '쾌청', '5턴 동안 햇살을 강하게 해서 불꽃타입 기술의 위력을 올린다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '불꽃'),
	(333, 'Hyper Beam', 'Normal', 'Special', 150, 90, 5, NULL, NULL, '파괴광선', '강한 광선을 상대에게 발사하여 공격한다. 다음 턴은 움직일 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '노말'),
	(334, 'Work Up', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '분발', '스스로 분발해서 공격과 특수공격을 올린다.', '0', 'user', '{"attack": 1, "special-attack": 1}', NULL, 'status', NULL, '노말'),
	(335, 'Payback', 'Dark', 'Physical', 50, 100, 10, NULL, NULL, '보복', '모아서 공격한다. 상대보다 뒤에 공격할 수 있으면 기술의 위력은 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(336, 'Raging Bull', 'Normal', 'Physical', 90, 100, 10, NULL, NULL, NULL, NULL, '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(337, 'Iron Head', 'Steel', 'Physical', 80, 100, 15, NULL, NULL, '아이언헤드', '강철과 같은 단단한 머리로 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(338, 'Bounce', 'Flying', 'Physical', 85, 85, 5, NULL, NULL, '뛰어오르다', '하늘 높이 뛰어올라 2턴째에 상대를 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '비행'),
	(339, 'Mist', 'Ice', 'Status', 0, 0, 30, NULL, NULL, '흰안개', '하얀 안개로 몸을 덮는다. 5턴 동안 상대에 의해 능력이 떨어지지 않게 된다.', '0', 'users-field', NULL, NULL, 'status', NULL, '얼음'),
	(340, 'Sheer Cold', 'Ice', 'Special', 0, 30, 5, NULL, NULL, '절대영도', '절대영도의 추위로 상대를 공격한다. 맞으면 일격에 기절한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '얼음'),
	(341, 'Transform', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '변신', '상대 포켓몬으로 변신하여 상대와 완전히 똑같은 기술을 사용할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(342, 'Thunder Fang', 'Electric', 'Physical', 65, 95, 15, NULL, NULL, '번개엄니', '전기를 모은 이빨로 문다. 상대를 풀죽게 하거나 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '전기'),
	(343, 'Pin Missile', 'Bug', 'Physical', 25, 95, 20, NULL, NULL, '바늘미사일', '날카로운 침을 상대에게 발사해서 공격한다. 2-5회 동안 연속으로 쓴다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
