	(345, 'Conversion 2', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '텍스처2', '상대가 마지막으로 쓴 기술에 저항할 수 있도록 자신의 타입을 변화시킨다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(346, 'Bind', 'Normal', 'Physical', 15, 85, 20, NULL, NULL, '조이기', '긴 몸이나 덩굴 등을 써서 4-5턴 동안 상대를 조여 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'physical', NULL, '노말'),
	(347, 'Block', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '블록', '양팔을 벌려 막아서서 상대의 도주로를 가로막아 도망칠 수 없게 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(348, 'Recycle', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '리사이클', '배틀 중에 사용하여 없어진 자신의 지닌 물건을 재생시켜 사용할 수 있게 한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(349, 'Stockpile', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '비축하기', '힘을 비축해서 자신의 방어와 특수방어를 올린다. 최대 3회까지 비축할 수 있다.', '0', 'user', '{"defense": 1, "special-defense": 1}', NULL, 'status', NULL, '노말'),
	(350, 'Swallow', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '꿀꺽', '비축된 힘을 꿀꺽해서 자신의 HP를 회복한다. 비축된 만큼 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(351, 'Yawn', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '하품', '큰 하품으로 졸음을 유도한다. 다음 턴에 상대를 잠듦 상태로 만든다.', '0', 'selected-pokemon', NULL, 'yawn', 'status', NULL, '노말'),
	(352, 'Sleep Talk', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '잠꼬대', '자신이 배운 기술 중 하나를 무작위로 날린다. 자신이 잠들어 있을 때만 쓸 수 있다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(353, 'Snore', 'Normal', 'Special', 50, 100, 15, NULL, NULL, '코골기', '자신이 잠들어있을 때 소음을 내어 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '노말'),
	(354, 'High Horsepower', 'Ground', 'Physical', 95, 95, 10, NULL, NULL, '10만마력', '온몸을 써서 상대에게 맹렬히 어택한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '땅'),
	(355, 'Freeze-Dry', 'Ice', 'Special', 70, 100, 20, NULL, NULL, '프리즈드라이', '상대를 급격히 차갑게 하여 얼음 상태로 만들 때가 있다. 물타입 포켓몬에게도 효과가 굉장해진다.', '0', 'selected-pokemon', NULL, 'freeze', 'special', NULL, '얼음'),
	(356, 'Overheat', 'Fire', 'Special', 130, 90, 5, NULL, NULL, '오버히트', '풀 파워로 상대를 공격한다. 쓰면 반동으로 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '불꽃'),
	(357, 'Sky Attack', 'Flying', 'Physical', 140, 90, 5, NULL, NULL, '불새', '2턴째에 상대를 공격한다. 가끔 풀죽게 만든다. 급소에도 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(358, 'Extreme Speed', 'Normal', 'Physical', 80, 100, 5, NULL, NULL, '신속', '눈에 보이지 않는 굉장한 속도로 상대에게 돌진하여 공격한다. 반드시 선제공격을 할 수 있다.', '2', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(359, 'Aura Sphere', 'Fighting', 'Special', 80, 0, 20, NULL, NULL, '파동탄', '몸속에서 파동의 힘을 끌어내 쏜다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '격투'),
	(360, 'Psystrike', 'Psychic', 'Special', 100, 100, 10, NULL, NULL, '사이코브레이크', '이상한 염력파를 실체화하여 상대를 공격한다. 물리적인 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(361, 'Baton Pass', 'Normal', 'Status', 0, 0, 40, NULL, NULL, '바톤터치', '교대 포켓몬과 바뀐다. 능력 변화는 바뀐 포켓몬이 그대로 이어받는다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(362, 'Leafage', 'Grass', 'Physical', 40, 100, 40, NULL, NULL, '나뭇잎', '잎을 상대에 맞춰 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(363, 'Flame Charge', 'Fire', 'Physical', 50, 100, 20, NULL, NULL, '니트로차지', '불꽃을 둘러 상대를 공격한다. 힘을 모아서 자신의 스피드를 올린다.', '0', 'selected-pokemon', '{"speed": 1}', NULL, 'physical', NULL, '불꽃'),
	(364, 'Eruption', 'Fire', 'Special', 150, 100, 5, NULL, NULL, '분화', '분노를 폭발시켜 상대를 공격한다. 자신의 HP가 적을수록 기술의 위력이 떨어진다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '불꽃'),
	(365, 'Follow Me', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '날따름', '자신에게 주목시켜 상대로부터의 공격을 모두 자신에게 향하게 한다.', '2', 'user', NULL, NULL, 'status', NULL, '노말'),
	(366, 'Coil', 'Poison', 'Status', 0, 0, 20, NULL, NULL, '똬리틀기', '똬리를 틀어서 집중한다. 자신의 공격과 방어와 명중률을 올린다.', '0', 'user', '{"attack": 1, "defense": 1, "accuracy": 1}', NULL, 'status', NULL, '독'),
	(367, 'Defog', 'Flying', 'Status', 0, 0, 15, NULL, NULL, '안개제거', '강한 바람으로 상대의 리플렉터나 빛의장막 등을 제거한다. 회피율도 떨어뜨린다.', '0', 'selected-pokemon', '{"evasion": -1}', NULL, 'status', NULL, '비행'),
	(368, 'Struggle Bug', 'Bug', 'Special', 50, 100, 20, NULL, NULL, '벌레의저항', '저항해서 상대를 공격한다. 상대의 특수공격을 떨어뜨린다.', '0', 'all-opponents', '{"special-attack": -1}', NULL, 'special', NULL, '벌레'),
	(369, 'Sticky Web', 'Bug', 'Status', 0, 0, 20, NULL, NULL, '끈적끈적네트', '상대의 주위에 끈적끈적한 네트를 둘러 펼쳐 교체되어 나온 상대의 스피드를 떨어뜨린다.', '0', 'opponents-field', NULL, NULL, 'status', NULL, '벌레'),
	(370, 'Baby-Doll Eyes', 'Fairy', 'Status', 0, 100, 30, NULL, NULL, '초롱초롱눈동자', '초롱초롱한 눈동자로 상대를 바라보며 공격을 떨어뜨린다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', '{"attack": -1}', NULL, 'status', NULL, '페어리'),
	(371, 'Air Cutter', 'Flying', 'Special', 60, 95, 25, NULL, NULL, '에어컷터', '날카로운 바람으로 상대를 베어 공격한다. 급소에 맞기 쉽다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '비행'),
	(372, 'Stored Power', 'Psychic', 'Special', 20, 100, 10, NULL, NULL, '어시스트파워', '축적된 파워로 상대를 공격한다. 자신의 능력이 올라가 있는 만큼 위력이 오른다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(373, 'Night Shade', 'Ghost', 'Special', 0, 100, 15, NULL, NULL, '나이트헤드', '무시무시한 환상을 보게 해서 자신의 레벨과 똑같은 만큼의 데미지를 상대에게 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '고스트'),
	(374, 'Psycho Shift', 'Psychic', 'Status', 0, 100, 10, NULL, NULL, '사이코시프트', '초능력으로 암시를 걸어서 자신에게 걸려 있는 상태 이상을 상대에게 옮긴다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(375, 'Power Swap', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '파워스웹', '초능력으로 자신과 상대의 공격과 특수공격의 능력 변화를 교체한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
