	(382, 'U-turn', 'Bug', 'Physical', 70, 100, 20, NULL, NULL, '유턴', '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
	(383, 'Tickle', 'Normal', 'Status', 0, 100, 20, NULL, NULL, '간지르기', '몸을 간질여 웃게 만들어서 상대의 공격과 방어를 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -1, "defense": -1}', NULL, 'status', NULL, '노말'),
	(384, 'Ingrain', 'Grass', 'Status', 0, 0, 20, NULL, NULL, '뿌리박기', '대지에 뿌리를 박아 매 턴마다 자신의 HP를 회복한다. 뿌리 박고 있으므로 교체할 수 없다.', '0', 'user', NULL, 'ingrain', 'status', NULL, '풀'),
