	(436, 'Flip Turn', 'Water', 'Physical', 60, 100, 20, NULL, NULL, '퀵턴', '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(437, 'Water Spout', 'Water', 'Special', 150, 100, 5, NULL, NULL, '해수스파우팅', '바닷물을 내뿜어 공격한다. 자신의 HP가 적을수록 기술의 위력이 떨어진다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '물'),
	(438, 'Noble Roar', 'Normal', 'Status', 0, 100, 30, NULL, NULL, '부르짖기', '우렁차게 부르짖어서 상대를 위협하여 상대의 공격과 특수공격을 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -1, "special-attack": -1}', NULL, 'status', NULL, '노말'),
	(439, 'Heat Crash', 'Fire', 'Physical', 0, 100, 10, NULL, NULL, '히트스탬프', '불타는 몸으로 상대에게 부딪쳐서 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '불꽃'),
	(440, 'Dragon Tail', 'Dragon', 'Physical', 60, 90, 10, NULL, NULL, '드래곤테일', '상대를 튕겨내서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', '-6', 'selected-pokemon', NULL, NULL, 'physical', NULL, '드래곤'),
	(441, 'Power Trip', 'Dark', 'Physical', 20, 100, 10, NULL, NULL, '기어오르기', '자신의 강함을 뻐기고 공격한다. 자신의 능력이 올라가 있는 만큼 위력이 오른다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(442, 'Cosmic Power', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '코스믹파워', '우주로부터 신비한 힘을 손에 넣음으로써 자신의 방어와 특수방어를 올린다.', '0', 'user', '{"defense": 1, "special-defense": 1}', NULL, 'status', NULL, '에스퍼'),
	(443, 'Magic Room', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '매직룸', '이상한 공간을 만든다. 5턴 동안 모든 포켓몬의 도구의 효과가 사라진다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(444, 'Hail', 'Ice', 'Status', 0, 0, 10, NULL, NULL, '싸라기눈', '5턴 동안 싸라기눈을 내리게 해 얼음타입이 아닌 포켓몬 모두에게 데미지를 준다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '얼음'),
	(445, 'Substitute', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '대타출동', '자신의 HP를 조금 깎아서 분신을 만든다. 분신은 자신의 대타가 된다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
