	(447, 'Gravity', 'Psychic', 'Status', 0, 0, 5, NULL, NULL, '중력', '5턴 동안 중력을 강하게 해서 부유나 하늘을 나는 기술을 사용할 수 없게 한다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(448, 'Mist Ball', 'Psychic', 'Special', 95, 100, 5, NULL, NULL, '미스트볼', '안개의 깃털로 둘러싸 공격한다. 상대의 특수공격을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-attack": -1}', NULL, 'special', NULL, '에스퍼'),
	(449, 'Luster Purge', 'Psychic', 'Special', 95, 100, 5, NULL, NULL, '라스트버지', '눈부신 빛을 발산하여 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '에스퍼'),
	(450, 'Origin Pulse', 'Water', 'Special', 110, 85, 10, NULL, NULL, '근원의파동', '파랗게 빛나는 무수한 광선으로 상대를 공격한다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '물'),
	(451, 'Precipice Blades', 'Ground', 'Physical', 120, 85, 10, NULL, NULL, '단애의칼', '대지의 힘을 칼날로 바꿔 상대를 공격한다.', '0', 'all-opponents', NULL, NULL, 'physical', NULL, '땅'),
	(452, 'Dragon Ascent', 'Flying', 'Physical', 120, 100, 5, NULL, NULL, '화룡점정', '넓은 하늘에서 급속으로 강하하여 상대를 공격한다. 자신의 방어와 특수방어가 떨어진다.', '0', 'selected-pokemon', '{"defense": -1, "special-defense": -1}', NULL, 'physical', NULL, '비행'),
	(453, 'Fly', 'Flying', 'Physical', 90, 95, 15, NULL, NULL, '공중날기', '1턴째에 하늘을 날아 2턴째에 상대를 공격한다. 알고 있는 도시로 날아갈 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(454, 'Meteor Mash', 'Steel', 'Physical', 90, 90, 10, NULL, NULL, '코멧펀치', '혜성과 같은 펀치를 날려서 상대를 공격한다. 자신의 공격이 올라갈 때가 있다.', '0', 'selected-pokemon', '{"attack": 1}', NULL, 'physical', NULL, '강철'),
	(455, 'Doom Desire', 'Steel', 'Special', 140, 100, 5, NULL, NULL, '파멸의소원', '기술을 사용한 2턴 뒤에 무수한 빛의 다발이 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '강철'),
	(456, 'Skill Swap', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '스킬스웹', '초능력으로 자신의 특성과 상대의 특성을 바꾼다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(457, 'Psycho Boost', 'Psychic', 'Special', 140, 90, 5, NULL, NULL, '사이코부스트', '풀 파워로 상대를 공격한다. 쓰면 반동으로 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '에스퍼'),
