	(460, 'Volt Switch', 'Electric', 'Special', 70, 100, 20, NULL, NULL, '볼트체인지', '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '전기'),
	(461, 'Metal Burst', 'Steel', 'Physical', 0, 100, 10, NULL, NULL, '메탈버스트', '기술을 쓰기 전에 마지막으로 받은 기술의 데미지를 늘려서 기술을 쓴 상대에게 돌려준다.', '0', 'specific-move', NULL, NULL, 'physical', NULL, '강철'),
