	(500, 'Vise Grip', 'Normal', 'Physical', 55, 100, 0, '30', 0, '찝기', '상대를 양쪽에서 집어서 데미지를 준다.', '0', NULL, NULL, NULL, NULL, NULL, '노말'),
	(501, 'Autotomize', 'Steel', 'Status', 0, 0, 15, NULL, NULL, '바디퍼지', '몸의 쓸모없는 부분을 깎는다. 자신의 스피드를 크게 올리고 체중도 가벼워진다.', '0', 'user', '{"speed": 2}', NULL, 'status', NULL, '강철'),
	(502, 'Gear Grind', 'Steel', 'Physical', 50, 85, 15, NULL, NULL, '기어소서', '강철의 기어를 상대에게 던져서 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(503, 'Shift Gear', 'Steel', 'Status', 0, 0, 10, NULL, NULL, '기어체인지', '톱니바퀴를 돌려서 자신의 공격을 올리는 것뿐만 아니라 스피드도 크게 올린다.', '0', 'user', '{"attack": 1, "speed": 2}', NULL, 'status', NULL, '강철'),
	(504, 'Gear Up', 'Steel', 'Status', 0, 0, 20, NULL, NULL, '어시스트기어', '기어를 넣는 것으로 특성 플러스와 마이너스의 공격과 특수공격이 올라간다.', '0', 'user-and-allies', '{"attack": 1, "special-attack": 1}', NULL, 'status', NULL, '강철'),
	(505, 'Psychic Terrain', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '사이코필드', '5턴 동안 땅에 있으면 선제공격을 받지 않는다. 에스퍼타입의 위력이 올라간다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(506, 'Frost Breath', 'Ice', 'Special', 60, 90, 10, NULL, NULL, '얼음숨결', '차가운 숨결을 상대에게 내뿜어 공격한다. 반드시 급소에 맞는다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '얼음'),
	(507, 'Water Shuriken', 'Water', 'Special', 15, 100, 20, NULL, NULL, '물수리검', '점액으로 만든 수리검을 2-5회 동안 연속으로 던진다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'special', NULL, '물'),
	(508, 'Revenge', 'Fighting', 'Physical', 60, 100, 10, NULL, NULL, '리벤지', '상대에게 기술을 받으면 그 상대에게 주는 데미지가 2배가 된다.', '-4', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(509, 'Head Charge', 'Normal', 'Physical', 120, 100, 15, NULL, NULL, '아프로브레이크', '굉장한 아프로 머리로 상대에게 돌진하여 공격한다. 자신도 조금 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(510, 'Fire Lash', 'Fire', 'Physical', 80, 100, 15, NULL, NULL, '불꽃채찍', '불타는 채찍으로 상대를 친다. 공격을 받은 상대는 방어가 떨어진다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '불꽃'),
	(511, 'Fiery Dance', 'Fire', 'Special', 80, 100, 10, NULL, NULL, '불꽃춤', '불꽃을 둘러 날개를 쳐서 공격한다. 자신의 특수공격이 오를 때가 있다.', '0', 'selected-pokemon', '{"special-attack": 1}', NULL, 'special', NULL, '불꽃'),
	(512, 'Sacred Sword', 'Fighting', 'Physical', 90, 100, 15, NULL, NULL, '성스러운칼', '긴 뿔로 베어 공격한다. 상대의 능력 변화에 관계없이 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(513, 'Horn Leech', 'Grass', 'Physical', 75, 100, 10, NULL, NULL, '우드호른', '뿔을 꿰찔러서 상대의 양분을 흡수한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(514, 'Bleakwind Storm', 'Flying', 'Special', 100, 80, 10, NULL, NULL, NULL, NULL, '0', 'all-opponents', NULL, NULL, 'special', NULL, '비행'),
	(515, 'Wildbolt Storm', 'Electric', 'Special', 100, 80, 10, NULL, NULL, NULL, NULL, '0', 'all-opponents', NULL, NULL, 'special', NULL, '전기'),
	(516, 'Fusion Flare', 'Fire', 'Special', 100, 100, 5, NULL, NULL, '크로스플레임', '거대한 불꽃을 내리친다. 거대한 천둥의 영향을 받아 기술의 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '불꽃'),
	(517, 'Blue Flare', 'Fire', 'Special', 130, 85, 5, NULL, NULL, '푸른불꽃', '아름다우면서도 격렬한 푸른불꽃으로 상대를 둘러싸서 공격한다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(518, 'Fusion Bolt', 'Electric', 'Physical', 100, 100, 5, NULL, NULL, '크로스썬더', '거대한 천둥을 내리친다. 거대한 불꽃의 영향을 받아 기술의 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '전기'),
	(519, 'Bolt Strike', 'Electric', 'Physical', 130, 85, 5, NULL, NULL, '뇌격', '방대한 전기를 몸에 둘러 상대에게 돌진해서 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '전기'),
	(520, 'Sandsear Storm', 'Ground', 'Special', 100, 80, 10, NULL, NULL, NULL, NULL, '0', 'all-opponents', NULL, NULL, 'special', NULL, '땅'),
	(521, 'Glaciate', 'Ice', 'Special', 65, 95, 10, NULL, NULL, '얼다세계', '차가운 냉기를 상대에게 내뿜어 공격한다. 상대의 스피드를 떨어뜨린다.', '0', 'all-opponents', '{"speed": -1}', NULL, 'special', NULL, '얼음'),
	(522, 'Secret Sword', 'Fighting', 'Special', 85, 100, 10, NULL, NULL, '신비의칼', '긴 뿔로 베어 공격한다. 뿔이 머금은 이상한 힘은 물리적인 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '격투'),
	(523, 'Relic Song', 'Normal', 'Special', 75, 100, 10, NULL, NULL, '옛노래', '옛노래를 상대에게 들려주고 마음에 호소하여 공격한다. 잠듦 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'sleep', 'special', NULL, '노말'),
	(524, 'Techno Blast', 'Normal', 'Special', 120, 100, 5, NULL, NULL, '테크노버스터', '광탄을 상대에게 방출한다. 자신이 지니고 있는 카세트에 의해 타입이 바뀐다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '노말'),
	(525, 'Topsy-Turvy', 'Dark', 'Status', 0, 0, 20, NULL, NULL, '뒤집어엎기', '상대에게 걸려 있는 모든 능력 변화를 뒤집어서 반대로 만든다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '악'),
	(526, 'Flying Press', 'Fighting', 'Physical', 100, 95, 10, NULL, NULL, '플라잉프레스', '공중에서 상대에게 다이브한다. 이 기술은 격투타입임과 동시에 비행타입이기도 하다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
