	(564, 'Cut', 'Normal', 'Physical', 50, 95, 30, '30', 0, '풀베기', '낫이나 발톱 등으로 상대를 베어 공격한다. 가느다란 나무도 자를 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(565, 'Photon Geyser', 'Psychic', 'Special', 100, 100, 5, NULL, NULL, '포톤가이저', '빛의 기둥으로 공격한다. 공격과 특수공격을 비교해서 높은 쪽으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(566, 'Prismatic Laser', 'Psychic', 'Special', 160, 100, 10, NULL, NULL, '프리즘레이저', '프리즘의 힘으로 강력한 광선을 발사한다. 다음 턴은 움직일 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(567, 'Magnet Bomb', 'Steel', 'Physical', 60, 0, 20, NULL, NULL, '마그넷봄', '상대에게 달라붙는 강철의 폭탄을 발사한다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(568, 'Fleur Cannon', 'Fairy', 'Special', 130, 90, 5, NULL, NULL, '플뢰르캐논', '강력한 빔을 발산한 후 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '페어리'),
	(569, 'Dual Chop', 'Dragon', 'Physical', 40, 90, 15, NULL, NULL, '더블촙', '몸의 단단한 부분으로 상대를 때려 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '드래곤'),
	(570, 'Spectral Thief', 'Ghost', 'Physical', 90, 100, 10, NULL, NULL, '섀도스틸', '상대의 그림자에 숨어들어 상대의 능력이 올라가는 것을 뺏어 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(571, 'Magic Coat', 'Psychic', 'Status', 0, 0, 15, NULL, NULL, '매직코트', '상대가 상태 이상이 되는 기술이나 씨뿌리기 등을 썼을 때 되받아친다.', '4', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(572, 'Trick', 'Psychic', 'Status', 0, 100, 10, NULL, NULL, '트릭', '상대의 빈틈을 노려 자신과 상대가 지닌 물건을 교환한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(573, 'Mind Blown', 'Fire', 'Special', 150, 100, 5, NULL, NULL, '깜짝헤드', '자신의 머리를 폭발시켜 주위의 모든 것을 공격한다. 자신도 데미지를 받는다.', '0', 'all-other-pokemon', NULL, NULL, 'special', NULL, '불꽃'),
	(574, 'Plasma Fists', 'Electric', 'Physical', 100, 100, 15, NULL, NULL, '플라스마피스트', '전기를 두른 주먹으로 공격한다. 노말타입 기술을 전기타입으로 바꿔버린다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '전기'),
	(575, 'Double Iron Bash', 'Steel', 'Physical', 60, 100, 5, NULL, NULL, '더블펀처', '가슴의 너트를 축으로 회전시켜 2번 연속 팔로 힘껏 친다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(576, 'Branch Poke', 'Grass', 'Physical', 40, 100, 40, '40', 0, '가지찌르기', '날카롭고 뾰족한 가지로 상대를 찔러서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(577, 'Court Change', 'Normal', 'Status', 0, 100, 10, NULL, NULL, '코트체인지', '이상한 힘으로 서로의 필드 효과를 교체한다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '노말'),
	(578, 'Stuff Cheeks', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '볼가득넣기', '지니고 있는 나무열매를 먹고 방어를 크게 올린다.', '0', 'user', '{"defense": 2}', NULL, 'status', NULL, '노말'),
	(579, 'Dual Wingbeat', 'Flying', 'Physical', 40, 90, 10, NULL, NULL, '더블윙', '날개를 상대에게 부딪쳐서 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(580, 'Leaf Tornado', 'Grass', 'Special', 65, 90, 10, NULL, NULL, '그래스믹서', '날카로운 잎사귀로 상대를 둘러싸서 공격한다. 명중률을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"accuracy": -1}', NULL, 'special', NULL, '풀'),
	(581, 'Jaw Lock', 'Dark', 'Physical', 80, 100, 10, NULL, NULL, '물고버티기', '어느 한쪽이 기절할 때까지 교체할 수 없게 된다. 한쪽의 포켓몬이 없어지면 효과가 사라진다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(582, 'Electrify', 'Electric', 'Status', 0, 0, 20, NULL, NULL, '송전', '상대가 기술을 쓰기 전에 송전하면 그 턴에 상대가 사용하는 기술은 전기타입이 된다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '전기'),
	(583, 'Grav Apple', 'Grass', 'Physical', 80, 100, 10, NULL, NULL, 'G의힘', '높은 곳에서 사과를 떨어뜨려서 데미지를 준다. 상대의 방어를 떨어뜨린다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '풀'),
	(584, 'Apple Acid', 'Grass', 'Special', 80, 100, 10, NULL, NULL, '사과산', '새콤한 사과에서 만들어 낸 산성 액체로 공격한다. 상대의 특수방어를 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '풀'),
	(585, 'Overdrive', 'Electric', 'Special', 80, 100, 10, NULL, NULL, '오버드라이브', '기타나 베이스를 쳐서 큰 울림과 강한 진동을 상대에게 전달하여 공격한다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '전기'),
	(586, 'Burn Up', 'Fire', 'Special', 130, 100, 5, NULL, NULL, '불사르기', '전신의 불꽃을 모두 태워서 큰 데미지를 준다. 자신의 불꽃타입이 없어진다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '불꽃'),
	(587, 'Magic Powder', 'Psychic', 'Status', 0, 100, 20, NULL, NULL, '마법가루', '마법가루를 날려서 상대를 에스퍼타입으로 바꾼다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(588, 'Confide', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '비밀이야기', '비밀 이야기를 하면서 상대의 집중력을 잃게 하여 상대의 특수공격을 떨어뜨린다.', '0', 'selected-pokemon', '{"special-attack": -1}', NULL, 'status', NULL, '노말'),
	(589, 'False Surrender', 'Dark', 'Physical', 80, 0, 10, NULL, NULL, '사죄의찌르기', '고개를 숙이는 척하면서 흐트러진 머리카락으로 찌른다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(590, 'Obstruct', 'Dark', 'Status', 0, 100, 10, NULL, NULL, '블로킹', '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다. 접촉한 상대의 방어를 크게 떨어뜨린다.', '4', 'user', NULL, NULL, 'status', NULL, '악'),
	(591, 'Submission', 'Fighting', 'Physical', 80, 80, 20, NULL, NULL, '지옥의바퀴', '땅에 자신과 함께 상대를 내던져 공격한다. 자신도 조금 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(592, 'Meteor Assault', 'Fighting', 'Physical', 150, 100, 5, NULL, NULL, '스타어설트', '굵은 줄기를 휘둘러서 공격한다. 단 자신도 비틀거리기 때문에 다음 턴은 움직일 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(593, 'No Retreat', 'Fighting', 'Status', 0, 0, 5, NULL, NULL, '배수의진', '자신의 모든 능력이 올라가지만 교체하거나 도망칠 수 없게 된다.', '0', 'user', '{"attack": 1, "defense": 1, "special-attack": 1, "special-defense": 1, "speed": 1}', NULL, 'status', NULL, '격투'),
	(594, 'Aurora Veil', 'Ice', 'Status', 0, 0, 20, NULL, NULL, '오로라베일', '5턴 동안 물리와 특수 기술의 데미지를 약하게 한다. 싸라기눈일 때만 쓸 수 있다.', '0', 'users-field', NULL, NULL, 'status', NULL, '얼음'),
	(595, 'Aura Wheel', 'Electric', 'Physical', 110, 100, 10, NULL, NULL, '오라휠', '볼주머니에 저장해둔 에너지로 공격하고 자신의 스피드를 올린다. 모르페코의 모습에 따라 타입이 바뀐다.', '0', 'selected-pokemon', '{"speed": 1}', NULL, 'physical', NULL, '전기'),
	(596, 'Bolt Beak', 'Electric', 'Physical', 85, 100, 10, NULL, NULL, '전격부리', '전기를 두른 부리로 찌른다. 상대보다 먼저 공격하면 기술의 위력은 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '전기'),
	(597, 'Avalanche', 'Ice', 'Physical', 60, 100, 10, NULL, NULL, '눈사태', '상대로부터 기술을 받으면 그 상대에 대해서 기술의 위력이 2배가 된다.', '-4', 'selected-pokemon', NULL, NULL, 'physical', NULL, '얼음'),
	(598, 'Fishious Rend', 'Water', 'Physical', 85, 100, 10, NULL, NULL, '아가미물기', '단단한 아가미로 문다. 상대보다 먼저 공격하면 기술의 위력은 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(599, 'Dynamax Cannon', 'Dragon', 'Special', 100, 100, 5, NULL, NULL, '다이맥스포', '코어에서 빔을 발사해서 공격한다. 상대가 다이맥스 중이면 데미지가 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '드래곤'),
	(600, 'Jungle Healing', 'Grass', 'Status', 0, 0, 10, NULL, NULL, '정글힐', '정글과 하나가 되어 자신과 배틀에 나와 있는 같은 편의 HP와 모든 상태를 회복한다.', '0', 'user-and-allies', NULL, NULL, 'status', NULL, '풀'),
	(601, 'Thunder Cage', 'Electric', 'Special', 80, 90, 15, NULL, NULL, '썬더프리즌', '전기가 흐르는 우리 안에 4-5턴 동안 상대를 가두어 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'special', NULL, '전기'),
	(602, 'Dragon Energy', 'Dragon', 'Special', 150, 100, 5, NULL, NULL, '드래곤에너지', '생명력을 파워로 바꿔서 상대를 공격한다. 자신의 HP가 적을수록 기술의 위력이 떨어진다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '드래곤'),
