	(704, 'Hurricane', 'Flying', 'Special', 110, 70, 10, NULL, NULL, '폭풍', '강렬한 바람으로 상대를 둘러싸서 공격한다. 상대를 혼란시킬 때가 있다.', '0', 'selected-pokemon', NULL, 'confusion', 'special', NULL, '비행'),
	(705, 'Brave Bird', 'Flying', 'Physical', 120, 100, 15, NULL, NULL, '브레이브버드', '날개를 접어 저공비행으로 돌격한다. 자신도 상당한 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(706, 'Laser Focus', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '예민해지기', '정신을 집중해서 다음 공격을 반드시 급소에 맞춘다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(707, 'Assurance', 'Dark', 'Physical', 60, 100, 10, NULL, NULL, '승부굳히기', '그 턴에 상대가 이미 데미지를 입었다면 기술의 위력은 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(708, 'Crunch', 'Dark', 'Physical', 80, 100, 15, NULL, NULL, '깨물어부수기', '날카로운 이빨로 상대를 깨물어 부숴서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '악'),
	(709, 'Sucker Punch', 'Dark', 'Physical', 70, 100, 5, NULL, NULL, '기습', '상대보다 먼저 공격할 수 있다. 상대가 쓴 기술이 공격기술이 아니면 실패한다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
