	(711, 'Endeavor', 'Normal', 'Physical', 0, 100, 5, NULL, NULL, '죽기살기', '상대의 HP가 자신의 HP와 같아지도록 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(712, 'Scary Face', 'Normal', 'Status', 0, 100, 10, NULL, NULL, '겁나는얼굴', '무서운 얼굴로 노려보고 겁주어 상대의 스피드를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"speed": -2}', NULL, 'status', NULL, '노말'),
	(713, 'Swords Dance', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '칼춤', '싸움의 춤을 격렬하게 추며 기세를 높인다. 자신의 공격을 크게 올린다.', '0', 'user', '{"attack": 2}', NULL, 'status', NULL, '노말'),
