	(775, 'Inferno', 'Fire', 'Special', 100, 50, 5, NULL, NULL, '연옥', '격렬한 불꽃으로 상대를 둘러싸 공격한다. 화상 상태로 만든다.', '0', 'selected-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(776, 'Fire Blast', 'Fire', 'Special', 110, 85, 5, NULL, NULL, '불대문자', '큰 대자의 불꽃으로 상대를 불태운다. 화상 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(777, 'Sing', 'Normal', 'Status', 0, 55, 15, NULL, NULL, '노래하기', '기분 좋은 예쁜 노랫소리를 들려주고 상대를 잠듦 상태로 만든다.', '0', 'selected-pokemon', NULL, 'sleep', 'status', NULL, '노말'),
	(778, 'Fake Tears', 'Dark', 'Status', 0, 100, 20, NULL, NULL, '거짓울음', '우는 척을 하며 눈물을 흘린다. 난처하게 만들어 상대의 특수방어를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -2}', NULL, 'status', NULL, '악'),
	(779, 'Facade', 'Normal', 'Physical', 70, 100, 20, NULL, NULL, '객기', '자신이 독, 마비, 화상 상태일 때 날리면 기술의 위력이 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(780, 'Body Slam', 'Normal', 'Physical', 85, 100, 15, NULL, NULL, '누르기', '몸 전체로 상대를 덮쳐 눌러 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '노말'),
