	(789, 'Sweet Scent', 'Normal', 'Status', 0, 100, 20, NULL, NULL, '달콤한향기', '향기로 상대의 회피율을 크게 떨어뜨린다. 풀밭 등에서 쓰면 포켓몬이 다가온다.', '0', 'all-opponents', '{"evasion": -2}', NULL, 'status', NULL, '노말'),
	(790, 'Mega Drain', 'Grass', 'Special', 40, 100, 15, NULL, NULL, '메가드레인', '양분을 흡수하여 공격한다. 상대에게 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '풀'),
	(791, 'Giga Drain', 'Grass', 'Special', 75, 100, 10, NULL, NULL, '기가드레인', '양분을 흡수하여 공격한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '풀'),
	(792, 'Grassy Terrain', 'Grass', 'Status', 0, 0, 10, NULL, NULL, '그래스필드', '5턴 동안 발밑을 그래스필드로 만든다. 땅에 있는 포켓몬은 매 턴 회복한다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '풀'),
