	(827, 'Roar', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '울부짖기', '상대를 도망가게 해서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', '-6', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(828, 'Reversal', 'Fighting', 'Physical', 0, 100, 15, NULL, NULL, '기사회생', '힘을 쥐어짜서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(829, 'Pound', 'Normal', 'Physical', 40, 100, 35, '35', 0, '막치기', '긴 꼬리나 손 등을 사용하여 상대를 때려서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(830, 'Mud Shot', 'Ground', 'Special', 55, 95, 15, NULL, NULL, '머드숏', '진흙 덩어리를 상대에게 내던져서 공격한다. 동시에 상대의 스피드를 떨어뜨린다.', '0', 'selected-pokemon', '{"speed": -1}', NULL, 'special', NULL, '땅'),
	(831, 'Rain Dance', 'Water', 'Status', 0, 0, 5, NULL, NULL, '비바라기', '5턴 동안 비를 내리게 하여 물타입 기술의 위력을 올린다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '물'),
	(832, 'Belly Drum', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '배북', '자신의 HP를 최대 HP의 절반만큼 감소시켜 자신의 공격을 최대로 올린다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(833, 'Teleport', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '순간이동', '야생 포켓몬과 배틀을 그만둔다. 마지막에 들어갔던 포켓몬센터가 있는 도시에도 갈 수 있다.', '-6', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(834, 'Reflect', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '리플렉터', '5턴 동안 이상한 장막으로 상대로부터 받는 물리공격의 데미지를 약하게 한다.', '0', 'users-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(835, 'Psycho Cut', 'Psychic', 'Physical', 70, 100, 20, NULL, NULL, '사이코커터', '실체화시킨 마음의 칼날로 상대를 베어 가른다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '에스퍼'),
	(836, 'Recover', 'Normal', 'Status', 0, 0, 5, NULL, NULL, 'HP회복', '세포를 재생시켜 자신의 최대 HP의 절반만큼 HP를 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(837, 'Psyshock', 'Psychic', 'Special', 80, 100, 10, NULL, NULL, '사이코쇼크', '이상한 염력파를 실체화하여 상대를 공격한다. 물리적인 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(838, 'Future Sight', 'Psychic', 'Special', 120, 100, 10, NULL, NULL, '미래예지', '기술을 사용한 2턴 뒤에 상대에게 염동력의 덩어리를 보내어 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(839, 'Calm Mind', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '명상', '조용히 정신을 통일하고 마음을 가라앉혀서 자신의 특수공격과 특수방어를 올린다.', '0', 'user', '{"special-attack": 1, "special-defense": 1}', NULL, 'status', NULL, '에스퍼'),
	(840, 'Power-Up Punch', 'Fighting', 'Physical', 40, 100, 20, NULL, NULL, '그로우펀치', '반복하여 때리면 점점 주먹이 단단해진다. 상대를 때리면 공격이 오른다.', '0', 'selected-pokemon', '{"attack": 1}', NULL, 'physical', NULL, '격투'),
	(841, 'Bullet Punch', 'Steel', 'Physical', 40, 100, 30, NULL, NULL, '불릿펀치', '탄환처럼 빠르고 단단한 펀치를 상대에게 날린다. 반드시 선제공격을 할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(842, 'Bulk Up', 'Fighting', 'Status', 0, 0, 20, NULL, NULL, '벌크업', '몸에 힘을 담아 근육을 두껍게 해서 자신의 공격과 방어를 올린다.', '0', 'user', '{"attack": 1, "defense": 1}', NULL, 'status', NULL, '격투'),
	(843, 'Detect', 'Fighting', 'Status', 0, 0, 5, NULL, NULL, '판별', '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', '4', 'user', NULL, NULL, 'status', NULL, '격투'),
	(844, 'Heavy Slam', 'Steel', 'Physical', 0, 100, 10, NULL, NULL, '헤비봄버', '무거운 몸으로 상대에게 부딪쳐 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(845, 'Infestation', 'Bug', 'Special', 20, 100, 20, NULL, NULL, '엉겨붙기', '4-5턴 동안 상대에게 엉겨 붙어서 공격한다. 그동안 상대는 도망갈 수 없다.', '0', 'selected-pokemon', NULL, 'trap', 'special', NULL, '벌레'),
	(846, 'Power Whip', 'Grass', 'Physical', 120, 85, 10, '10', 0, '파워휩', '덩굴이나 촉수를 세차게 흔들어 상대를 힘껏 쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(847, 'Leaf Storm', 'Grass', 'Special', 130, 90, 5, NULL, NULL, '리프스톰', '뾰족한 잎사귀로 상대에게 바람을 일으킨다. 사용하면 반동으로 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '풀'),
	(848, 'Wrap', 'Normal', 'Physical', 15, 90, 20, NULL, NULL, '김밥말이', '긴 몸이나 덩굴 등을 사용해 4-5턴 동안 상대를 휘감아 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'physical', NULL, '노말'),
	(849, 'Hex', 'Ghost', 'Special', 65, 100, 10, NULL, NULL, '병상첨병', '엎친 데 덮친 격으로 공격한다. 상태 이상인 상대에게 큰 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '고스트'),
	(850, 'Acid Armor', 'Poison', 'Status', 0, 0, 20, NULL, NULL, '녹기', '세포의 변화로 액체가 되어 자신의 방어를 크게 올린다.', '0', 'user', '{"defense": 2}', NULL, 'status', NULL, '독'),
	(851, 'Surf', 'Water', 'Special', 90, 100, 15, NULL, NULL, '파도타기', '큰 파도로 자신의 주위에 있는 포켓몬을 공격한다. 물 위도 헤엄쳐서 나아간다.', '0', 'all-other-pokemon', NULL, NULL, 'special', NULL, '물'),
	(852, 'Reflect Type', 'Normal', 'Status', 0, 0, 15, NULL, NULL, '미러타입', '상대의 타입을 반사해서 자신도 똑같은 타입이 된다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(853, 'Rock Polish', 'Rock', 'Status', 0, 0, 20, NULL, NULL, '록커트', '자신의 몸을 갈아 공기의 저항을 적게 한다. 스피드를 크게 올릴 수 있다.', '0', 'user', '{"speed": 2}', NULL, 'status', NULL, '바위'),
	(854, 'Smack Down', 'Rock', 'Physical', 50, 100, 15, NULL, NULL, '떨어뜨리기', '돌이나 구슬을 던져서 날고 있는 상대를 공격한다. 맞은 상대는 땅에 떨어진다.', '0', 'selected-pokemon', NULL, 'unknown', 'physical', NULL, '바위'),
	(855, 'Self-Destruct', 'Normal', 'Physical', 200, 100, 5, NULL, NULL, '자폭', '폭발을 일으켜서 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서 기절하게 된다.', '0', 'all-other-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(856, 'Stealth Rock', 'Rock', 'Status', 0, 0, 20, NULL, NULL, '스텔스록', '상대의 주위에 무수한 바위를 띄워 교체해서 나온 상대 포켓몬에게 데미지를 준다.', '0', 'opponents-field', NULL, NULL, 'status', NULL, '바위'),
	(857, 'Rock Blast', 'Rock', 'Physical', 25, 90, 10, NULL, NULL, '락블레스트', '단단한 암석을 상대에게 발사하여 공격한다. 2-5회 동안 연속으로 쓴다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '바위'),
	(858, 'Explosion', 'Normal', 'Physical', 250, 100, 5, NULL, NULL, '대폭발', '큰 폭발로 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서는 기절한다.', '0', 'all-other-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(859, 'Stone Edge', 'Rock', 'Physical', 100, 80, 5, NULL, NULL, '스톤에지', '뾰족한 바위를 상대에게 꿰찔러서 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '바위'),
	(860, 'Double Hit', 'Normal', 'Physical', 35, 90, 10, NULL, NULL, '더블어택', '꼬리 등을 써서 상대를 때려 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(861, 'Curse', 'Ghost', 'Status', 0, 0, 10, NULL, NULL, '저주', '기술을 쓰는 포켓몬이 고스트타입일 때와 그 이외의 타입일 때는 효과가 다르다.', '0', 'specific-move', NULL, NULL, 'status', NULL, '고스트'),
	(862, 'Headbutt', 'Normal', 'Physical', 70, 100, 15, NULL, NULL, '박치기', '머리를 내밀어 곧장 돌진하여 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(863, 'Electro Ball', 'Electric', 'Special', 0, 100, 10, NULL, NULL, '일렉트릭볼', '전기 덩어리를 상대에게 부딪쳐서 공격한다. 상대보다 스피드가 빠를수록 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '전기'),
	(864, 'Magnet Rise', 'Electric', 'Status', 0, 0, 10, NULL, NULL, '전자부유', '전기로 만든 자력의 힘으로 허공에 뜬다. 5턴 동안 부유할 수 있다.', '0', 'user', NULL, NULL, 'status', NULL, '전기'),
	(865, 'Flash Cannon', 'Steel', 'Special', 80, 100, 10, NULL, NULL, '러스터캐논', '몸의 빛을 한곳에 모아서 힘을 쏜다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '강철'),
	(866, 'Discharge', 'Electric', 'Special', 80, 100, 15, NULL, NULL, '방전', '눈부신 전격으로 자신의 주위에 있는 포켓몬을 공격한다. 마비 상태로 만들 때가 있다.', '0', 'all-other-pokemon', NULL, 'paralysis', 'special', NULL, '전기'),
	(867, 'Metal Sound', 'Steel', 'Status', 0, 85, 40, NULL, NULL, '금속음', '금속을 긁을 때 나는 듯한 싫은 소리를 들려준다. 상대의 특수방어를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -2}', NULL, 'status', NULL, '강철'),
	(868, 'Lock-On', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '록온', '조준을 잘 맞춰 다음 공격이 반드시 상대에게 명중하도록 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(869, 'Zap Cannon', 'Electric', 'Special', 120, 50, 5, NULL, NULL, '전자포', '대포처럼 전기를 발사해서 공격한다. 상대를 마비 상태로 만든다.', '0', 'selected-pokemon', NULL, 'paralysis', 'special', NULL, '전기'),
	(870, 'Electric Terrain', 'Electric', 'Status', 0, 0, 10, NULL, NULL, '일렉트릭필드', '5턴 동안 발밑을 일렉트릭필드로 만든다. 땅에 있는 포켓몬은 잠들지 않게 된다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '전기'),
	(871, 'Steel Wing', 'Steel', 'Physical', 70, 90, 25, NULL, NULL, '강철날개', '단단한 날개를 상대에게 부딪쳐서 공격한다. 자신의 방어가 올라갈 때가 있다.', '0', 'selected-pokemon', '{"defense": 1}', NULL, 'physical', NULL, '강철'),
	(872, 'False Swipe', 'Normal', 'Physical', 40, 100, 40, NULL, NULL, '칼등치기', '상대의 HP가 반드시 1만큼 남도록 조절하여 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(873, 'Leaf Blade', 'Grass', 'Physical', 90, 100, 15, NULL, NULL, '리프블레이드', '잎사귀를 칼처럼 이용해 상대를 베어 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
