	(875, 'Acupressure', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '경혈찌르기', '경혈을 눌러 몸을 활성화시킨다. 능력 중 하나를 크게 올린다.', '0', 'user-or-ally', NULL, NULL, 'status', NULL, '노말'),
	(876, 'Thrash', 'Normal', 'Physical', 120, 100, 10, NULL, NULL, '난동부리기', '2-3턴 동안 마구 난동 부려서 상대를 공격한다. 난동 부린 뒤에는 혼란에 빠진다.', '0', 'random-opponent', NULL, NULL, 'physical', NULL, '노말'),
	(877, 'Encore', 'Normal', 'Status', 0, 100, 5, NULL, NULL, '앵콜', '상대가 마지막으로 사용한 기술을 3턴 동안 계속 쓰게 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(878, 'Ice Shard', 'Ice', 'Physical', 40, 100, 30, NULL, NULL, '얼음뭉치', '얼음 덩어리를 순식간에 만들어 상대에게 빠르게 쏜다. 반드시 선제공격을 할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '얼음'),
	(879, 'Rest', 'Psychic', 'Status', 0, 0, 5, NULL, NULL, '잠자기', '2턴 동안 계속 잠잔다. 자신의 HP와 상태 이상을 모두 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(880, 'Aurora Beam', 'Ice', 'Special', 65, 100, 20, NULL, NULL, '오로라빔', '무지개색의 빔을 상대에게 발사하여 공격한다. 공격을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"attack": -1}', NULL, 'special', NULL, '얼음'),
	(881, 'Brine', 'Water', 'Special', 65, 100, 10, NULL, NULL, '소금물', '상대가 HP의 절반 정도 상처를 입고 있으면 기술의 위력이 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '물'),
	(882, 'Dive', 'Water', 'Physical', 80, 100, 10, NULL, NULL, '다이빙', '1턴째에 잠수했다가 2턴째에 떠올라 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
