	(886, 'Sludge', 'Poison', 'Special', 65, 100, 20, NULL, NULL, '오물공격', '더러운 오물을 상대에게 내던져서 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(887, 'Minimize', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '작아지기', '몸을 축소하여 작게 보임으로써 자신의 회피율을 크게 올린다.', '0', 'user', '{"evasion": 2}', NULL, 'status', NULL, '노말'),
	(888, 'Sludge Bomb', 'Poison', 'Special', 90, 100, 10, NULL, NULL, '오물폭탄', '더러운 오물을 상대에게 내던져서 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(889, 'Belch', 'Poison', 'Special', 120, 90, 10, NULL, NULL, '트림', '상대를 향해 트림을 하여 데미지를 준다. 나무열매를 먹지 않으면 쓸 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '독'),
	(890, 'Memento', 'Dark', 'Status', 0, 100, 10, NULL, NULL, '추억의선물', '자신은 기절하게 되지만 그 대신 상대의 공격과 특수공격을 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -2, "special-attack": -2}', NULL, 'status', NULL, '악'),
	(891, 'Withdraw', 'Water', 'Status', 0, 0, 40, NULL, NULL, '껍질에숨기', '껍질에 숨어 몸을 보호하여 자신의 방어를 올린다.', '0', 'user', '{"defense": 1}', NULL, 'status', NULL, '물'),
	(892, 'Whirlpool', 'Water', 'Special', 35, 85, 15, NULL, NULL, '바다회오리', '세차게 소용돌이치는 물속에 4-5턴 동안 상대를 가두어 공격한다.', '0', 'selected-pokemon', NULL, 'trap', 'special', NULL, '물'),
	(893, 'Protect', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '방어', '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', '4', 'user', NULL, NULL, 'status', NULL, '노말'),
	(894, 'Razor Shell', 'Water', 'Physical', 75, 95, 10, NULL, NULL, '셸블레이드', '날카로운 조개껍질로 베어 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '물'),
	(895, 'Shell Smash', 'Normal', 'Status', 0, 0, 15, NULL, NULL, '껍질깨기', '껍질을 깨서 자신의 방어와 특수방어를 떨어뜨리지만 공격과 특수공격, 스피드를 크게 올린다.', '0', 'user', '{"defense": -1, "special-defense": -1, "attack": 2, "special-attack": 2, "speed": 2}', NULL, 'status', NULL, '노말'),
	(896, 'Icicle Crash', 'Ice', 'Physical', 85, 90, 10, NULL, NULL, '고드름떨구기', '큰 고드름을 격렬하게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '얼음'),
	(897, 'Spikes', 'Ground', 'Status', 0, 0, 20, NULL, NULL, '압정뿌리기', '상대의 발밑에 압정을 뿌린다. 교체된 상대 포켓몬에게 데미지를 준다.', '0', 'opponents-field', NULL, NULL, 'status', NULL, '땅'),
	(898, 'Lick', 'Ghost', 'Physical', 30, 100, 30, NULL, NULL, '핥기', '긴 혀로 상대를 핥아서 공격한다. 마비 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'paralysis', 'physical', NULL, '고스트'),
	(899, 'Shadow Sneak', 'Ghost', 'Physical', 40, 100, 30, NULL, NULL, '야습', '그림자를 늘려 상대의 배후에서 공격한다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(900, 'Dark Pulse', 'Dark', 'Special', 80, 100, 15, NULL, NULL, '악의파동', '몸에서 악의로 가득한 무서운 오라를 발한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '악'),
	(901, 'Shadow Ball', 'Ghost', 'Special', 80, 100, 15, NULL, NULL, '섀도볼', '까만 그림자의 덩어리를 내던져서 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '고스트'),
	(902, 'Shadow Claw', 'Ghost', 'Physical', 70, 100, 15, NULL, NULL, '섀도크루', '그림자로 만든 날카로운 발톱으로 상대를 베어 가른다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(903, 'Phantom Force', 'Ghost', 'Physical', 90, 100, 10, NULL, NULL, '고스트다이브', '1턴째에 어디론가 사라져서 2턴째에 상대를 공격한다. 기술 방어를 무시하고 공격할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(904, 'Rock Slide', 'Rock', 'Physical', 75, 90, 10, NULL, NULL, '스톤샤워', '큰 바위를 세차게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'all-opponents', NULL, NULL, 'physical', NULL, '바위'),
	(905, 'Breaking Swipe', 'Dragon', 'Physical', 60, 100, 15, NULL, NULL, '와이드브레이커', '강인한 꼬리를 세차게 휘둘러서 상대를 공격한다. 상대의 공격을 떨어뜨린다.', '0', 'all-opponents', '{"attack": -1}', NULL, 'physical', NULL, '드래곤'),
	(906, 'Iron Tail', 'Steel', 'Physical', 100, 75, 15, NULL, NULL, '아이언테일', '단단한 꼬리로 상대를 힘껏 쳐서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '강철'),
	(907, 'Head Smash', 'Rock', 'Physical', 150, 80, 5, NULL, NULL, '양날박치기', '목숨을 걸고 혼신의 힘으로 상대에게 박치기를 한다. 자신도 굉장한 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '바위'),
	(908, 'Swagger', 'Normal', 'Status', 0, 85, 15, NULL, NULL, '뽐내기', '상대를 화내게 해서 혼란시킨다. 분노로 상대의 공격은 크게 올라가 버린다.', '0', 'selected-pokemon', '{"attack": 2}', 'confusion', 'status', NULL, '노말'),
	(909, 'Switcheroo', 'Dark', 'Status', 0, 100, 10, NULL, NULL, '바꿔치기', '눈에 보이지 않는 속도로 자신과 상대가 지닌 물건을 교환한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '악'),
	(910, 'Stomp', 'Normal', 'Physical', 65, 100, 20, NULL, NULL, '짓밟기', '큰 발로 상대를 짓밟아서 공격한다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(911, 'Flail', 'Normal', 'Physical', 0, 100, 15, NULL, NULL, '바둥바둥', '바둥바둥 난동 부려서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(912, 'Slam', 'Normal', 'Physical', 80, 75, 20, '20', 0, '힘껏치기', '긴 꼬리나 덩굴 등을 사용해 상대를 힘껏 쳐서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(913, 'Crabhammer', 'Water', 'Physical', 100, 90, 10, NULL, NULL, '찝게햄머', '큰 집게를 상대에게 내리쳐서 공격한다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(914, 'Guillotine', 'Normal', 'Physical', 0, 30, 5, NULL, NULL, '가위자르기', '큰 집게로 상대를 베어 갈라 공격한다. 맞으면 일격에 기절한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(915, 'Hammer Arm', 'Fighting', 'Physical', 100, 90, 10, NULL, NULL, '암해머', '강하고 무거운 주먹을 휘둘러 데미지를 준다. 자신의 스피드가 떨어진다.', '0', 'selected-pokemon', '{"speed": -1}', NULL, 'physical', NULL, '격투'),
	(916, 'Wide Guard', 'Rock', 'Status', 0, 0, 10, NULL, NULL, '와이드가드', '같은 편 전원에게 향하는 공격을 1턴 동안 막는다. ', '3', 'users-field', NULL, NULL, 'status', NULL, '바위'),
	(917, 'Eerie Impulse', 'Electric', 'Status', 0, 100, 15, NULL, NULL, '괴전파', '몸에서 괴전파를 내어 상대에게 쏨으로써 특수공격을 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'status', NULL, '전기'),
	(918, 'Charge Beam', 'Electric', 'Special', 50, 90, 10, NULL, NULL, '차지빔', '전격의 다발을 상대에게 발사한다. 전기를 모아서 자신의 특수공격을 올릴 때가 있다.', '0', 'selected-pokemon', '{"special-attack": 1}', NULL, 'special', NULL, '전기'),
	(919, 'Mirror Coat', 'Psychic', 'Special', 0, 100, 20, NULL, NULL, '미러코트', '상대에게 받은 특수공격의 데미지를 2배로 만들어 그 상대에게 돌려준다.', '-5', 'specific-move', NULL, NULL, 'special', NULL, '에스퍼'),
	(920, 'Magnetic Flux', 'Electric', 'Status', 0, 0, 20, NULL, NULL, '자기장조작', '자기장 조작으로 인해 특성 플러스와 마이너스의 방어, 특수방어가 오른다.', '0', 'user-and-allies', '{"defense": 1, "special-defense": 1}', NULL, 'status', NULL, '전기'),
