	(944, 'Smog', 'Poison', 'Special', 30, 70, 20, NULL, NULL, '스모그', '더러운 가스를 상대에게 내뿜어 공격한다. 독 상태로 만들 때가 있다.', '0', 'selected-pokemon', NULL, 'poison', 'special', NULL, '독'),
	(945, 'Clear Smog', 'Poison', 'Special', 50, 0, 15, NULL, NULL, '클리어스모그', '특수한 진흙 덩어리를 상대에게 내던져서 공격한다. 능력 변화를 원래대로 돌린다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '독'),
	(946, 'Destiny Bond', 'Ghost', 'Status', 0, 0, 5, NULL, NULL, '길동무', '기술을 쓴 뒤 공격을 받아 기절했을 때 길동무의 대상도 기절하게 한다.', '0', 'user', NULL, NULL, 'status', NULL, '고스트'),
	(947, 'Heat Wave', 'Fire', 'Special', 95, 90, 10, NULL, NULL, '열풍', '뜨거운 숨결을 상대에게 내뿜어 공격한다. 화상 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'burn', 'special', NULL, '불꽃'),
