	(949, 'Copycat', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '흉내쟁이', '직전에 나온 기술을 흉내 내어 같은 기술을 쓴다. 기술이 나오지 않았으면 실패한다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(950, 'Covet', 'Normal', 'Physical', 60, 100, 25, NULL, NULL, '탐내다', '귀엽게 애교부리며 상대에게 다가가 지니고 있는 도구를 뺏는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(951, 'Sweet Kiss', 'Fairy', 'Status', 0, 75, 10, NULL, NULL, '천사의키스', '천사처럼 귀엽게 키스하여 상대를 혼란시킨다.', '0', 'selected-pokemon', NULL, 'confusion', 'status', NULL, '페어리'),
	(952, 'Echoed Voice', 'Normal', 'Special', 40, 100, 15, NULL, NULL, '에코보이스', '울리는 목소리로 상대를 공격한다. 매 턴 누군가 기술을 계속해서 쓰면 위력이 올라간다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '노말'),
	(953, 'Life Dew', 'Water', 'Status', 0, 0, 10, NULL, NULL, '생명의물방울', '신비한 물을 흩뿌려서 자신과 배틀에 나와 있는 같은 편의 HP를 회복한다.', '0', 'user-and-allies', NULL, NULL, 'status', NULL, '물'),
	(954, 'Fling', 'Dark', 'Physical', 0, 100, 10, NULL, NULL, '내던지기', '지니게 한 도구를 재빠르게 내던져서 공격한다. 도구에 따라 위력과 효과가 바뀐다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(955, 'Heal Pulse', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '치유파동', '치유파동을 날려서 최대 HP의 절반만큼 상대의 HP를 회복한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(956, 'Soft-Boiled', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '알낳기', '자신의 최대 HP 절반을 회복한다. 동료에게 HP를 나누어 줄 수도 있다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(957, 'Last Resort', 'Normal', 'Physical', 140, 100, 5, NULL, NULL, '뒀다쓰기', '배틀 중에 기억하고 있는 기술을 모두 사용하면 그때부터 쓸 수 있는 필살기이다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(958, 'Healing Wish', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '치유소원', '자신은 기절하지만 교대하여 나오는 포켓몬의 상태 이상과 HP를 회복한다.', '0', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(959, 'Acid Spray', 'Poison', 'Special', 40, 100, 20, NULL, NULL, '애시드봄', '상대를 녹이는 액체를 토해내서 공격한다. 상대의 특수방어를 크게 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -2}', NULL, 'special', NULL, '독'),
	(960, 'Ancient Power', 'Rock', 'Special', 60, 100, 5, NULL, NULL, '원시의힘', '원시의 힘으로 공격한다. 자신의 모든 능력이 오를 때가 있다.', '0', 'selected-pokemon', '{"attack": 1, "defense": 1, "special-attack": 1, "special-defense": 1, "speed": 1}', NULL, 'special', NULL, '바위'),
	(961, 'Dragon Pulse', 'Dragon', 'Special', 85, 100, 10, '10', 0, '용의파동', '큰 입으로 충격파를 일으켜서 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '드래곤'),
	(962, 'Dragon Dance', 'Dragon', 'Status', 0, 0, 20, NULL, NULL, '용의춤', '신비롭고 힘센 춤을 격렬하게 춘다. 자신의 공격과 스피드를 올린다.', '0', 'user', '{"attack": 1, "speed": 1}', NULL, 'status', NULL, '드래곤'),
	(963, 'Waterfall', 'Water', 'Physical', 80, 100, 15, NULL, NULL, '폭포오르기', '굉장한 기세로 상대에게 돌진한다. 상대를 풀죽게 만들 때가 있다. 폭포도 거슬러 올라갈 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '물'),
	(964, 'Power Gem', 'Rock', 'Special', 80, 100, 20, '20', 0, '파워젬', '보석처럼 반짝이는 빛을 발사하여 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '바위'),
	(965, 'Dream Eater', 'Psychic', 'Special', 100, 100, 15, NULL, NULL, '꿈먹기', '잠자고 있는 상대의 꿈을 먹어 공격한다. 데미지의 절반을 HP로 회복한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '에스퍼'),
	(966, 'Double Team', 'Normal', 'Status', 0, 0, 15, NULL, NULL, '그림자분신', '재빠른 움직임으로 분신을 만들어 상대를 혼란시켜 회피율을 올린다.', '0', 'user', '{"evasion": 1}', NULL, 'status', NULL, '노말'),
	(967, 'Powder Snow', 'Ice', 'Special', 40, 100, 25, NULL, NULL, '눈싸라기', '차가운 가랑눈을 상대에게 내뿜어 공격한다. 얼음 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'freeze', 'special', NULL, '얼음'),
	(968, 'Lovely Kiss', 'Normal', 'Status', 0, 75, 10, NULL, NULL, '악마의키스', '무서운 얼굴로 키스한다. 상대를 잠듦 상태로 만든다.', '0', 'selected-pokemon', NULL, 'sleep', 'status', NULL, '노말'),
	(969, 'Mean Look', 'Normal', 'Status', 0, 0, 5, NULL, NULL, '검은눈빛', '빨려 들어갈 것 같은 까만 눈빛으로 가만히 응시하여 상대를 배틀에서 도망갈 수 없게 한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '노말'),
	(970, 'Blizzard', 'Ice', 'Special', 110, 70, 5, NULL, NULL, '눈보라', '세찬 눈보라를 상대에게 내뿜어 공격한다. 얼음 상태로 만들 때가 있다.', '0', 'all-opponents', NULL, 'freeze', 'special', NULL, '얼음'),
	(971, 'Shock Wave', 'Electric', 'Special', 60, 0, 20, NULL, NULL, '전격파', '전격을 재빠르게 상대에게 날린다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '전기'),
	(972, 'Lava Plume', 'Fire', 'Special', 80, 100, 15, NULL, NULL, '분연', '새빨간 불꽃으로 자신의 주위에 있는 포켓몬을 공격한다. 화상 상태로 만들 때가 있다.', '0', 'all-other-pokemon', NULL, 'burn', 'special', NULL, '불꽃'),
	(973, 'Sunny Day', 'Fire', 'Status', 0, 0, 5, NULL, NULL, '쾌청', '5턴 동안 햇살을 강하게 해서 불꽃타입 기술의 위력을 올린다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '불꽃'),
	(974, 'Hyper Beam', 'Normal', 'Special', 150, 90, 5, NULL, NULL, '파괴광선', '강한 광선을 상대에게 발사하여 공격한다. 다음 턴은 움직일 수 없다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '노말'),
	(975, 'Work Up', 'Normal', 'Status', 0, 0, 30, NULL, NULL, '분발', '스스로 분발해서 공격과 특수공격을 올린다.', '0', 'user', '{"attack": 1, "special-attack": 1}', NULL, 'status', NULL, '노말'),
	(976, 'Payback', 'Dark', 'Physical', 50, 100, 10, NULL, NULL, '보복', '모아서 공격한다. 상대보다 뒤에 공격할 수 있으면 기술의 위력은 2배가 된다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
