	(1082, 'Power Trip', 'Dark', 'Physical', 20, 100, 10, NULL, NULL, '기어오르기', '자신의 강함을 뻐기고 공격한다. 자신의 능력이 올라가 있는 만큼 위력이 오른다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(1083, 'Cosmic Power', 'Psychic', 'Status', 0, 0, 20, NULL, NULL, '코스믹파워', '우주로부터 신비한 힘을 손에 넣음으로써 자신의 방어와 특수방어를 올린다.', '0', 'user', '{"defense": 1, "special-defense": 1}', NULL, 'status', NULL, '에스퍼'),
	(1084, 'Magic Room', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '매직룸', '이상한 공간을 만든다. 5턴 동안 모든 포켓몬의 도구의 효과가 사라진다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(1085, 'Hail', 'Ice', 'Status', 0, 0, 10, NULL, NULL, '싸라기눈', '5턴 동안 싸라기눈을 내리게 해 얼음타입이 아닌 포켓몬 모두에게 데미지를 준다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '얼음'),
	(1086, 'Substitute', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '대타출동', '자신의 HP를 조금 깎아서 분신을 만든다. 분신은 자신의 대타가 된다.', '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(1087, 'Shed Tail', 'Normal', 'Status', 0, 0, 10, NULL, NULL, NULL, NULL, '0', 'user', NULL, NULL, 'status', NULL, '노말'),
	(1088, 'Gravity', 'Psychic', 'Status', 0, 0, 5, NULL, NULL, '중력', '5턴 동안 중력을 강하게 해서 부유나 하늘을 나는 기술을 사용할 수 없게 한다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(1089, 'Mist Ball', 'Psychic', 'Special', 95, 100, 5, NULL, NULL, '미스트볼', '안개의 깃털로 둘러싸 공격한다. 상대의 특수공격을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-attack": -1}', NULL, 'special', NULL, '에스퍼'),
	(1090, 'Luster Purge', 'Psychic', 'Special', 95, 100, 5, NULL, NULL, '라스트버지', '눈부신 빛을 발산하여 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '에스퍼'),
	(1091, 'Origin Pulse', 'Water', 'Special', 110, 85, 10, NULL, NULL, '근원의파동', '파랗게 빛나는 무수한 광선으로 상대를 공격한다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '물'),
	(1092, 'Precipice Blades', 'Ground', 'Physical', 120, 85, 10, NULL, NULL, '단애의칼', '대지의 힘을 칼날로 바꿔 상대를 공격한다.', '0', 'all-opponents', NULL, NULL, 'physical', NULL, '땅'),
	(1093, 'Dragon Ascent', 'Flying', 'Physical', 120, 100, 5, NULL, NULL, '화룡점정', '넓은 하늘에서 급속으로 강하하여 상대를 공격한다. 자신의 방어와 특수방어가 떨어진다.', '0', 'selected-pokemon', '{"defense": -1, "special-defense": -1}', NULL, 'physical', NULL, '비행'),
	(1094, 'Fly', 'Flying', 'Physical', 90, 95, 15, NULL, NULL, '공중날기', '1턴째에 하늘을 날아 2턴째에 상대를 공격한다. 알고 있는 도시로 날아갈 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(1095, 'Meteor Mash', 'Steel', 'Physical', 90, 90, 10, NULL, NULL, '코멧펀치', '혜성과 같은 펀치를 날려서 상대를 공격한다. 자신의 공격이 올라갈 때가 있다.', '0', 'selected-pokemon', '{"attack": 1}', NULL, 'physical', NULL, '강철'),
	(1096, 'Doom Desire', 'Steel', 'Special', 140, 100, 5, NULL, NULL, '파멸의소원', '기술을 사용한 2턴 뒤에 무수한 빛의 다발이 상대를 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '강철'),
	(1097, 'Skill Swap', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '스킬스웹', '초능력으로 자신의 특성과 상대의 특성을 바꾼다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(1098, 'Psycho Boost', 'Psychic', 'Special', 140, 90, 5, NULL, NULL, '사이코부스트', '풀 파워로 상대를 공격한다. 쓰면 반동으로 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '에스퍼'),
	(1099, 'Raging Fury', 'Fire', 'Physical', 120, 100, 10, NULL, NULL, NULL, NULL, '0', 'random-opponent', NULL, NULL, 'physical', NULL, '불꽃'),
	(1100, 'Fell Stinger', 'Bug', 'Physical', 50, 100, 25, NULL, NULL, '마지막일침', '이 기술을 사용하여 상대를 쓰러뜨리면 공격이 크게 오른다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
	(1101, 'Volt Switch', 'Electric', 'Special', 70, 100, 20, NULL, NULL, '볼트체인지', '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '전기'),
	(1102, 'Metal Burst', 'Steel', 'Physical', 0, 100, 10, NULL, NULL, '메탈버스트', '기술을 쓰기 전에 마지막으로 받은 기술의 데미지를 늘려서 기술을 쓴 상대에게 돌려준다.', '0', 'specific-move', NULL, NULL, 'physical', NULL, '강철'),
	(1103, 'Aromatic Mist', 'Fairy', 'Status', 0, 0, 20, NULL, NULL, '아로마미스트', '신비한 아로마 향으로 같은 편의 특수방어를 올린다. ', '0', 'ally', '{"special-defense": 1}', NULL, 'status', NULL, '페어리'),
	(1104, 'Attack Order', 'Bug', 'Physical', 90, 100, 15, NULL, NULL, '공격지령', '부하를 불러내어 상대를 향해서 공격시킨다. 급소에 맞기 쉽다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '벌레'),
	(1105, 'Defend Order', 'Bug', 'Status', 0, 0, 10, NULL, NULL, '방어지령', '부하를 불러내어 자신의 몸을 뒤덮게 한다. 방어와 특수방어를 올릴 수 있다.', '0', 'user', '{"defense": 1, "special-defense": 1}', NULL, 'status', NULL, '벌레'),
	(1106, 'Strength Sap', 'Grass', 'Status', 0, 100, 10, NULL, NULL, '힘흡수', '상대 공격력과 동일하게 자신의 HP를 회복한다. 그리고 상대의 공격을 떨어뜨린다.', '0', 'selected-pokemon', '{"attack": -1}', NULL, 'status', NULL, '풀'),
