	(1144, 'Shift Gear', 'Steel', 'Status', 0, 0, 10, NULL, NULL, '기어체인지', '톱니바퀴를 돌려서 자신의 공격을 올리는 것뿐만 아니라 스피드도 크게 올린다.', '0', 'user', '{"attack": 1, "speed": 2}', NULL, 'status', NULL, '강철'),
	(1145, 'Gear Up', 'Steel', 'Status', 0, 0, 20, NULL, NULL, '어시스트기어', '기어를 넣는 것으로 특성 플러스와 마이너스의 공격과 특수공격이 올라간다.', '0', 'user-and-allies', '{"attack": 1, "special-attack": 1}', NULL, 'status', NULL, '강철'),
	(1146, 'Psychic Terrain', 'Psychic', 'Status', 0, 0, 10, NULL, NULL, '사이코필드', '5턴 동안 땅에 있으면 선제공격을 받지 않는다. 에스퍼타입의 위력이 올라간다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '에스퍼'),
	(1147, 'Frost Breath', 'Ice', 'Special', 60, 90, 10, NULL, NULL, '얼음숨결', '차가운 숨결을 상대에게 내뿜어 공격한다. 반드시 급소에 맞는다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '얼음'),
	(1148, 'Water Shuriken', 'Water', 'Special', 15, 100, 20, NULL, NULL, '물수리검', '점액으로 만든 수리검을 2-5회 동안 연속으로 던진다. 반드시 선제공격할 수 있다.', '1', 'selected-pokemon', NULL, NULL, 'special', NULL, '물'),
	(1149, 'Revenge', 'Fighting', 'Physical', 60, 100, 10, NULL, NULL, '리벤지', '상대에게 기술을 받으면 그 상대에게 주는 데미지가 2배가 된다.', '-4', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(1150, 'Head Charge', 'Normal', 'Physical', 120, 100, 15, NULL, NULL, '아프로브레이크', '굉장한 아프로 머리로 상대에게 돌진하여 공격한다. 자신도 조금 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '노말'),
	(1151, 'Fire Lash', 'Fire', 'Physical', 80, 100, 15, NULL, NULL, '불꽃채찍', '불타는 채찍으로 상대를 친다. 공격을 받은 상대는 방어가 떨어진다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '불꽃'),
	(1152, 'Fiery Dance', 'Fire', 'Special', 80, 100, 10, NULL, NULL, '불꽃춤', '불꽃을 둘러 날개를 쳐서 공격한다. 자신의 특수공격이 오를 때가 있다.', '0', 'selected-pokemon', '{"special-attack": 1}', NULL, 'special', NULL, '불꽃'),
	(1153, 'Sacred Sword', 'Fighting', 'Physical', 90, 100, 15, NULL, NULL, '성스러운칼', '긴 뿔로 베어 공격한다. 상대의 능력 변화에 관계없이 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
	(1154, 'Horn Leech', 'Grass', 'Physical', 75, 100, 10, NULL, NULL, '우드호른', '뿔을 꿰찔러서 상대의 양분을 흡수한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(1155, 'Bleakwind Storm', 'Flying', 'Special', 100, 80, 10, NULL, NULL, NULL, NULL, '0', 'all-opponents', NULL, NULL, 'special', NULL, '비행'),
