	(1209, 'Fleur Cannon', 'Fairy', 'Special', 130, 90, 5, NULL, NULL, '플뢰르캐논', '강력한 빔을 발산한 후 자신의 특수공격이 크게 떨어진다.', '0', 'selected-pokemon', '{"special-attack": -2}', NULL, 'special', NULL, '페어리'),
	(1210, 'Dual Chop', 'Dragon', 'Physical', 40, 90, 15, NULL, NULL, '더블촙', '몸의 단단한 부분으로 상대를 때려 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '드래곤'),
	(1211, 'Spectral Thief', 'Ghost', 'Physical', 90, 100, 10, NULL, NULL, '섀도스틸', '상대의 그림자에 숨어들어 상대의 능력이 올라가는 것을 뺏어 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '고스트'),
	(1212, 'Magic Coat', 'Psychic', 'Status', 0, 0, 15, NULL, NULL, '매직코트', '상대가 상태 이상이 되는 기술이나 씨뿌리기 등을 썼을 때 되받아친다.', '4', 'user', NULL, NULL, 'status', NULL, '에스퍼'),
	(1213, 'Trick', 'Psychic', 'Status', 0, 100, 10, NULL, NULL, '트릭', '상대의 빈틈을 노려 자신과 상대가 지닌 물건을 교환한다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(1214, 'Mind Blown', 'Fire', 'Special', 150, 100, 5, NULL, NULL, '깜짝헤드', '자신의 머리를 폭발시켜 주위의 모든 것을 공격한다. 자신도 데미지를 받는다.', '0', 'all-other-pokemon', NULL, NULL, 'special', NULL, '불꽃'),
	(1215, 'Plasma Fists', 'Electric', 'Physical', 100, 100, 15, NULL, NULL, '플라스마피스트', '전기를 두른 주먹으로 공격한다. 노말타입 기술을 전기타입으로 바꿔버린다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '전기'),
	(1216, 'Double Iron Bash', 'Steel', 'Physical', 60, 100, 5, NULL, NULL, '더블펀처', '가슴의 너트를 축으로 회전시켜 2번 연속 팔로 힘껏 친다. 상대를 풀죽게 만들 때가 있다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '강철'),
	(1217, 'Branch Poke', 'Grass', 'Physical', 40, 100, 40, '40', 0, '가지찌르기', '날카롭고 뾰족한 가지로 상대를 찔러서 공격한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '풀'),
	(1218, 'Court Change', 'Normal', 'Status', 0, 100, 10, NULL, NULL, '코트체인지', '이상한 힘으로 서로의 필드 효과를 교체한다.', '0', 'entire-field', NULL, NULL, 'status', NULL, '노말'),
	(1219, 'Stuff Cheeks', 'Normal', 'Status', 0, 0, 10, NULL, NULL, '볼가득넣기', '지니고 있는 나무열매를 먹고 방어를 크게 올린다.', '0', 'user', '{"defense": 2}', NULL, 'status', NULL, '노말'),
	(1220, 'Dual Wingbeat', 'Flying', 'Physical', 40, 90, 10, NULL, NULL, '더블윙', '날개를 상대에게 부딪쳐서 공격한다. 2회 연속으로 데미지를 준다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '비행'),
	(1221, 'Leaf Tornado', 'Grass', 'Special', 65, 90, 10, NULL, NULL, '그래스믹서', '날카로운 잎사귀로 상대를 둘러싸서 공격한다. 명중률을 떨어뜨릴 때가 있다.', '0', 'selected-pokemon', '{"accuracy": -1}', NULL, 'special', NULL, '풀'),
	(1222, 'Jaw Lock', 'Dark', 'Physical', 80, 100, 10, NULL, NULL, '물고버티기', '어느 한쪽이 기절할 때까지 교체할 수 없게 된다. 한쪽의 포켓몬이 없어지면 효과가 사라진다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(1223, 'Electrify', 'Electric', 'Status', 0, 0, 20, NULL, NULL, '송전', '상대가 기술을 쓰기 전에 송전하면 그 턴에 상대가 사용하는 기술은 전기타입이 된다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '전기'),
	(1224, 'Grav Apple', 'Grass', 'Physical', 80, 100, 10, NULL, NULL, 'G의힘', '높은 곳에서 사과를 떨어뜨려서 데미지를 준다. 상대의 방어를 떨어뜨린다.', '0', 'selected-pokemon', '{"defense": -1}', NULL, 'physical', NULL, '풀'),
	(1225, 'Apple Acid', 'Grass', 'Special', 80, 100, 10, NULL, NULL, '사과산', '새콤한 사과에서 만들어 낸 산성 액체로 공격한다. 상대의 특수방어를 떨어뜨린다.', '0', 'selected-pokemon', '{"special-defense": -1}', NULL, 'special', NULL, '풀'),
	(1226, 'Overdrive', 'Electric', 'Special', 80, 100, 10, NULL, NULL, '오버드라이브', '기타나 베이스를 쳐서 큰 울림과 강한 진동을 상대에게 전달하여 공격한다.', '0', 'all-opponents', NULL, NULL, 'special', NULL, '전기'),
	(1227, 'Burn Up', 'Fire', 'Special', 130, 100, 5, NULL, NULL, '불사르기', '전신의 불꽃을 모두 태워서 큰 데미지를 준다. 자신의 불꽃타입이 없어진다.', '0', 'selected-pokemon', NULL, NULL, 'special', NULL, '불꽃'),
	(1228, 'Magic Powder', 'Psychic', 'Status', 0, 100, 20, NULL, NULL, '마법가루', '마법가루를 날려서 상대를 에스퍼타입으로 바꾼다.', '0', 'selected-pokemon', NULL, NULL, 'status', NULL, '에스퍼'),
	(1229, 'Confide', 'Normal', 'Status', 0, 0, 20, NULL, NULL, '비밀이야기', '비밀 이야기를 하면서 상대의 집중력을 잃게 하여 상대의 특수공격을 떨어뜨린다.', '0', 'selected-pokemon', '{"special-attack": -1}', NULL, 'status', NULL, '노말'),
	(1230, 'False Surrender', 'Dark', 'Physical', 80, 0, 10, NULL, NULL, '사죄의찌르기', '고개를 숙이는 척하면서 흐트러진 머리카락으로 찌른다. 공격은 반드시 명중한다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '악'),
	(1231, 'Obstruct', 'Dark', 'Status', 0, 100, 10, NULL, NULL, '블로킹', '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다. 접촉한 상대의 방어를 크게 떨어뜨린다.', '4', 'user', NULL, NULL, 'status', NULL, '악'),
	(1232, 'Submission', 'Fighting', 'Physical', 80, 80, 20, NULL, NULL, '지옥의바퀴', '땅에 자신과 함께 상대를 내던져 공격한다. 자신도 조금 데미지를 입는다.', '0', 'selected-pokemon', NULL, NULL, 'physical', NULL, '격투'),
